/**
 * 故宫 3D 虚拟游览主程序
 */

class ForbiddenCityApp {
  constructor() {
    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.controls = null;
    this.postProcessing = null;
    this.collisionManager = null;

    this.currentQuality = 'high';
    this.isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ||
      (/Macintosh/i.test(navigator.userAgent) && navigator.maxTouchPoints > 1);
    this.lastLocation = null;
    this.lastShadowUpdate = 0;
    this.shadowObjects = [];
    this.disposed = false;
    this._animate = this.animate.bind(this);
    this._onResize = this.onResize.bind(this);

    // 加载管理
    this.loadingManager = new THREE.LoadingManager();
    this.loadingManager.onProgress = (url, loaded, total) => {
      const progress = (loaded / total) * 100;
      this.updateLoadingProgress(progress, url);
    };
    this.loadingManager.onLoad = () => {
      this.onLoadComplete();
    };
  }

  /**
   * 初始化
   */
  async init() {
    // 显示加载界面
    this.showLoading();

    // 尺寸监听必须在加载前注册：之前放在加载完成后，手机在加载过程中转横屏，
    // 画布会停留在竖屏尺寸，横屏时只占左半边、右边黑屏。
    // 微信 / iOS 转屏时 resize 可能不触发或触发时尺寸还没更新，所以再加 orientationchange、
    // visualViewport 两路兜底，并在转屏后延迟复查；动画循环里也会每帧比对尺寸。
    this._onOrientationChange = () => {
      this.onResize();
      clearTimeout(this._resizeTimer1);
      clearTimeout(this._resizeTimer2);
      this._resizeTimer1 = setTimeout(this._onResize, 200);
      this._resizeTimer2 = setTimeout(this._onResize, 600);
    };
    window.addEventListener('resize', this._onResize);
    window.addEventListener('orientationchange', this._onOrientationChange);
    window.visualViewport?.addEventListener('resize', this._onResize);

    // 说明：本项目的纹理（Canvas）和几何体都是程序化同步生成的，不经过任何 Loader，
    // LoadingManager 不会自动收到进度，onLoad 也不会触发（之前加载界面卡在 0% 的根因）。
    // 这里把每个构建步骤手动登记到 LoadingManager：先全部 itemStart，每完成一步 itemEnd，
    // 这样 onProgress 能正常推进进度条，最后一步完成时 onLoad 自动触发并关闭加载界面。
    const quality = this.isMobile ? 'low' : 'high';
    const steps = [
      ['渲染器', () => {
        this.createScene();
        this.createCamera();
        this.createRenderer();
        this.shadowSetup = new ShadowSetup(this.renderer);
        this.shadowSetup.init(quality);
      }],
      ['材质贴图', async () => {
        // 手机用 512 档贴图，桌面用 1024 档；加载失败的贴图自动回退为程序化贴图
        const maxAniso = this.renderer.capabilities.getMaxAnisotropy();
        this.library = new TextureLibrary({
          quality: this.isMobile ? 'sd' : 'hd',
          anisotropy: Math.min(maxAniso, this.isMobile ? 2 : 8),
        });
        const stepIndex = steps.findIndex(([name]) => name === '材质贴图');
        await this.library.load((done, total) => {
          const progress = ((stepIndex + done / Math.max(total, 1)) / steps.length) * 100;
          this.updateLoadingProgress(progress, `材质贴图 ${done}/${total}`);
        });
      }],
      ['天空与光照', () => {
        this.environment = new Environment(this.scene, this.renderer, this.library);
        this.environment.init();
        this.environment.setQuality(quality === 'high');
      }],
      ['宫殿建筑', () => {
        this.palaceBuilder = new PalaceBuilder(this.scene, this.library);
        this.palaceBuilder.buildAll(PALACE_LAYOUT);
      }],
      ['宫墙与庑房', () => {
        this.enclosure = new Enclosure(this.scene, this.library).build();
      }],
      ['御花园', () => {
        const garden = PALACE_LAYOUT.find(item => item.type === 'garden');
        this.garden = new GardenBuilder(this.scene, this.library).build(garden);
        // 静态场景（中轴/宫墙/御花园）进入阴影 LOD 列表；分区网格由 ZoneManager 回调增删
        this.scene.traverse(object => {
          if (object.isMesh) this.shadowObjects.push(object);
        });
      }],
      ['东西六宫与两路宫殿', () => {
        // 碰撞管理器先建：ZoneManager 加载区时要往里注册带 tag 的碰撞体
        this.collisionManager = new CollisionManager();
        this.zoneManager = new ZoneManager();
        this.zoneManager.onLoad = (_id, group) => group.traverse(o => { if (o.isMesh) this.shadowObjects.push(o); });
        this.zoneManager.onUnload = (_id, group) => {
          const gone = new Set();
          group.traverse(o => { if (o.isMesh) gone.add(o); });
          this.shadowObjects = this.shadowObjects.filter(o => !gone.has(o));
        };
        ZONES.forEach(zone => this.zoneManager.register(zone));
        const start = LAYOUT.START_POSITION;
        this.zoneManager.init(this.scene, this.library, this.collisionManager, { x: start.x, z: start.z });
      }],
      ['碰撞检测', () => {
        this.collisionManager.addColliders(this.palaceBuilder.getColliders());
        this.collisionManager.addWalkables(this.palaceBuilder.getWalkables());
        this.collisionManager.addColliders(this.enclosure.getColliders());
        this.collisionManager.addColliders(this.garden.getColliders());
        this.collisionManager.addWalkables(this.garden.getWalkables());
        // 分区的 colliders/walkables 由 ZoneManager 带 tag 注册/移除；regions 启动时已覆盖全部分区
        this.collisionManager.setRegions(this.zoneManager.getRegions());
        // 所有可进入房间（世界坐标，含门/掩体/刷怪点），后续玩法从这里取
        this.rooms = this.zoneManager.getRooms();
        // S 档内景：按距离流式加载 GLB（失败回退 B 档）
        // base：部署到子路径（如 GitHub Pages /forbidden-city-3d/）时，模型与 draco/basis 解码器都要带前缀；根路径部署时为 ''
        const base = (import.meta.env?.BASE_URL ?? '/').replace(/\/$/, '');
        this.interiors = new InteriorLoader(this.scene, this.collisionManager, { renderer: this.renderer, base });
      }],
      ['控制器', () => {
        this.controls = new FirstPersonControls(this.camera, document.body, this.collisionManager);
        const start = LAYOUT.START_POSITION;
        this.controls.setPosition(start.x, start.y, start.z);
        // 相机默认朝向 -Z（背对故宫），出生时转身面向北边的午门
        this.controls.lookAt(0, LAYOUT.WUMEN_Z);
        this.bindWelcomeOverlay();
      }],
      ['后期处理', () => {
        this.postProcessing = new PostProcessing(this.renderer, this.scene, this.camera);
        this.postProcessing.init(quality);
        this.currentQuality = quality;
      }],
      ['界面', () => {
        this.ambience = new Ambience();
        this.createUI();
        this.bindAudioStart();
        this.perfHUD = new PerfHUD(this.renderer, {
          zoneProvider: () => ({
            current: this.zoneManager?.getCurrentId() ?? '-',
            loaded: this.zoneManager?.getLoadedIds() ?? []
          })
        });
      }],
    ];

    steps.forEach(([name]) => this.loadingManager.itemStart(name));

    try {
      for (const [name, run] of steps) {
        await run();
        this.loadingManager.itemEnd(name);
        // 让出一帧，让浏览器把进度条刷新到屏幕上
        await new Promise(resolve => requestAnimationFrame(() => setTimeout(resolve, 0)));
        if (this.disposed) return;
      }
    } catch (err) {
      this.showLoadingError(err);
      throw err;
    }

    // 加载期间可能已经转过屏，进入渲染前按当前窗口尺寸校正一次
    this.onResize();

    // 开始动画循环
    this.animate();

    console.log('故宫 3D 初始化完成');
  }

  /**
   * 桌面端欢迎遮罩：加载完成后显示，点击锁定鼠标后隐藏，按 ESC 解锁后重新显示
   */
  bindWelcomeOverlay() {
    if (this.isMobile) return;
    const overlay = document.getElementById('welcome-overlay');
    if (!overlay) return;
    this._onLock = () => { overlay.style.display = 'none'; };
    this._onUnlock = () => { overlay.style.display = this.minimap?.visible || this.settingsMenu?.visible ? 'none' : 'flex'; };
    this.controls.controls.addEventListener('lock', this._onLock);
    this.controls.controls.addEventListener('unlock', this._onUnlock);
  }

  /**
   * 初始化出错时，在加载界面上直接显示错误，避免一直卡在进度条
   */
  showLoadingError(err) {
    const progressText = document.getElementById('progress-text');
    if (progressText) {
      progressText.style.color = '#ff6b6b';
      progressText.textContent = `加载失败：${err && err.message ? err.message : err}（详情见控制台）`;
    }
  }

  /**
   * 创建场景
   */
  createScene() {
    this.scene = new THREE.Scene();
  }

  /**
   * 创建相机
   */
  createCamera() {
    // 70° 视场更接近人眼观感；远裁剪面 2500 米：真实米制下宫城南北 961 m，从午门外要能看到神武门与天际线远景环
    this.camera = new THREE.PerspectiveCamera(
      70,
      window.innerWidth / window.innerHeight,
      0.1,
      2500
    );
  }

  /**
   * 创建渲染器
   */
  createRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      antialias: !this.isMobile,
      powerPreference: 'high-performance',
    });

    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(this.getPixelRatio(this.isMobile ? 'low' : 'high'));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    // 电影感色调映射：高光不过曝、红墙黄瓦饱和度自然
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 0.7; // 降低曝光，避免天空过亮

    // 画布必须放进 #scene-container 里：
    // 之前直接 append 到 body 末尾，而 #scene-container 已占满 100% 视口，
    // 画布被挤到可视区域下方（body overflow:hidden），所以加载完是一片黑屏
    const canvas = this.renderer.domElement;
    canvas.id = 'scene-canvas';
    const container = document.getElementById('scene-container') || document.body;
    container.appendChild(canvas);
  }

  /**
   * 创建 UI
   */
  createUI() {
    // 位置信息面板
    this.locationPanel = document.createElement('div');
    this.locationPanel.id = 'location-panel';
    this.locationPanel.style.cssText = `
      position: fixed;
      top: 20px;
      left: 20px;
      padding: 15px 20px;
      background: rgba(0, 0, 0, 0.6);
      color: white;
      border-radius: 8px;
      font-size: 16px;
      z-index: 1000;
      font-family: Arial, sans-serif;
    `;
    document.body.appendChild(this.locationPanel);

    // 操作说明面板
    const helpPanel = document.createElement('div');
    helpPanel.id = 'help-panel';
    helpPanel.style.cssText = `
      position: fixed;
      top: 80px;
      left: 20px;
      padding: 15px 20px;
      background: rgba(0, 0, 0, 0.6);
      color: white;
      border-radius: 8px;
      font-size: 14px;
      z-index: 1000;
      font-family: Arial, sans-serif;
      line-height: 1.6;
    `;

    if (this.isMobile) {
      helpPanel.innerHTML = `
        <strong>操作说明</strong><br>
        左下角方向盘：前后左右移动<br>
        同一方向推住2秒：跑起来<br>
        手指拖动屏幕：调整视角<br>
        右下角"跳"：跳过矮墙栏杆<br>
        右上角地图：点开看全图<br>
        右下角按钮：锁定视角<br>
        午门/神武门两端有马道可登城楼
      `;
      // 手机屏幕小，说明面板 8 秒后自动淡出，避免遮挡画面
      helpPanel.style.transition = 'opacity 0.6s ease';
      setTimeout(() => { helpPanel.style.opacity = '0'; }, 8000);
    } else {
      helpPanel.innerHTML = `
        <strong>操作说明</strong><br>
        WASD / 方向键：移动<br>
        长按2秒：自动快走<br>
        鼠标：视角<br>
        空格：跳跃<br>
        M键：小地图<br>
        午门/神武门两端马道可登城楼<br>
        点击屏幕开始游览
      `;
    }
    document.body.appendChild(helpPanel);

    // 小地图（按 M 键显示/隐藏）
    // 移动端额外常驻右上角预览，点击展开全图
    this.teleport = new Teleport(this.controls, this.zoneManager, this.collisionManager);
    this._onTeleportKey = event => {
      if (event.repeat || event.ctrlKey || event.metaKey || event.altKey || /^(INPUT|TEXTAREA|SELECT)$/.test(event.target?.tagName)) return;
      const index = Number(event.key) - 1;
      if (/^[1-8]$/.test(event.key)) this.teleport.go(TELEPORT.POINTS[index].target);
    };
    window.addEventListener('keydown', this._onTeleportKey);
    this.minimap = new Minimap({ items: this.zoneManager.getMapItems(), preview: this.isMobile, onTeleport: name => this.teleport.go(name), onToggle: visible => {
      this.settingsMenu?.setMapMode(visible, this.minimap.container);
      if (this.settingsTourSession?.paused) {
        this.settingsTourSession.mapChanged(visible);
        return;
      }
      // 打开地图：释放鼠标以便缩放/点击，但保留键盘移动（WASD 走动、Q/E 转向）；关闭：重新锁定视角
      this.controls.setFreeMove?.(visible);
      // unlock 事件会重新显示欢迎遮罩，先同步隐藏；之后的 unlock 回调也会检查 minimap.visible
      const overlay = document.getElementById('welcome-overlay');
      if (visible && overlay) overlay.style.display = 'none';
      if (visible) this.controls.unlock();
      else { try { this.controls.lock(); } catch { /* 需要用户手势时忽略，点击画面即可重新进入 */ } }
    } });

    // 设置菜单（按 ESC 显示）
    this.settingsTourSession = new SettingsTourSession({
      controls: this.controls,
      isMobile: this.isMobile,
      minimap: this.minimap,
      welcomeOverlay: document.getElementById('welcome-overlay'),
    });
    this.settingsMenu = new SettingsMenu(document.body);
    this.settingsMenu.init({
      initialQuality: this.currentQuality,
      initialSound: true,
      onOpen: () => this.settingsTourSession.open(),
      onResume: () => this.settingsTourSession.resume(),
      onQualityChange: (quality) => {
        this.toggleQuality(quality);
      },
      onSoundToggle: (enabled) => {
        if (!enabled) {
          this.ambience.setMuted(true);
        } else {
          this.ambience.start();
          this.ambience.setMuted(false);
        }
      },
    });

    // 绑定 ESC 键打开设置菜单
    this._onKeyDown = (event) => {
      if (event.code === 'Escape' && !event.repeat) {
        event.preventDefault();
        this.settingsMenu.toggle();
      }
    };
    window.addEventListener('keydown', this._onKeyDown);
  }

  /** 浏览器要求用户手势后才能启动音频：桌面锁定鼠标时、移动端首次触摸时启动 */
  bindAudioStart() {
    this._startAudio = () => this.ambience?.start();
    this.controls.controls.addEventListener('lock', this._startAudio);
    window.addEventListener('touchstart', this._startAudio, { passive: true });
    window.addEventListener('pointerdown', this._startAudio);
  }

  /** 是否位于某座门楼的门洞内（用于音效混响） */
  isInGatePassage(position) {
    return PALACE_LAYOUT.some(item => item.type === 'gate' &&
      Math.abs(position.x - item.position.x) < item.dimensions.width * 0.075 &&
      Math.abs(position.z - item.position.z) < item.dimensions.depth / 2);
  }

  /**
   * 切换画质
   */
  getPixelRatio(quality) {
    const cap = quality === 'low' ? 1 : (this.isMobile ? PERFORMANCE.MOBILE_MAX_PIXEL_RATIO : 2);
    return Math.min(window.devicePixelRatio || 1, cap);
  }

  toggleQuality(quality = this.currentQuality === 'high' ? 'low' : 'high') {
    // The menu supplies the chosen value. Do not invert it a second time.
    // No-argument calls still toggle for keyboard/testing callers.
    if (quality !== 'high' && quality !== 'low') throw new Error(`Unsupported quality: ${quality}`);
    this.currentQuality = quality;

    // 更新渲染设置
    this.renderer.setPixelRatio(this.getPixelRatio(this.currentQuality));
    this.postProcessing.setQuality(this.currentQuality);
    this.environment.setQuality(this.currentQuality === 'high');
    this.shadowSetup.setQuality(this.currentQuality);
    this.lastShadowUpdate = 0;
    if (this.settingsMenu) {
      this.settingsMenu.currentQuality = this.currentQuality;
      this.settingsMenu.updateQualityButton();
    }
  }

  /**
   * 更新位置信息
   */
  updateLocationInfo() {
    const position = this.controls.getPosition();
    const location = this.collisionManager.getCurrentLocation(position);
    const zone = ZONES.find(item => item.id === this.zoneManager.getCurrentId())?.name ?? '宫城';
    const label = `${zone} › ${location}`;
    if (label === this.lastLocation) return;
    this.lastLocation = label;
    this.locationPanel.replaceChildren();
    const heading = document.createElement('strong');
    heading.textContent = '当前位置';
    this.locationPanel.append(heading, document.createElement('br'), document.createTextNode(label));
  }

  /**
   * 显示加载界面
   */
  showLoading() {
    const loading = document.getElementById('loading-screen');
    if (loading) {
      loading.style.display = 'flex';
    }
  }

  /**
   * 更新加载进度
   */
  updateLoadingProgress(progress, stepName = '') {
    const progressBar = document.getElementById('progress-bar');
    const progressText = document.getElementById('progress-text');

    if (progressBar) {
      progressBar.style.width = `${progress}%`;
    }
    if (progressText) {
      const suffix = stepName ? (stepName.includes('/') ? `（${stepName}）` : `（${stepName}已完成）`) : '';
      progressText.textContent = `加载中... ${Math.round(progress)}%${suffix}`;
    }
  }

  /**
   * 加载完成
   */
  onLoadComplete() {
    this.loadingTimeout = setTimeout(() => {
      if (this.disposed) return;
      const loading = document.getElementById('loading-screen');
      if (loading) {
        loading.style.display = 'none';
      }

      // 移动端自动开始，桌面端显示欢迎遮罩，点击后锁定鼠标开始游览
      if (this.isMobile) {
        console.log('移动端自动开始');
      } else {
        const overlay = document.getElementById('welcome-overlay');
        if (overlay && !this.controls.controls.isLocked) {
          overlay.style.display = 'flex';
        }
        console.log('点击屏幕开始游览');
      }
    }, 500);
  }

  /**
   * 窗口大小调整
   */
  getViewportSize() {
    // 以布局视口为准；部分安卓 WebView 转屏后 innerWidth 更新滞后，取 documentElement 兜底
    const width = Math.max(1, Math.round(window.innerWidth || document.documentElement.clientWidth));
    const height = Math.max(1, Math.round(window.innerHeight || document.documentElement.clientHeight));
    return { width, height };
  }

  onResize() {
    if (this.disposed || !this.camera || !this.renderer) return;
    const { width, height } = this.getViewportSize();
    this._lastSize = `${width}x${height}`;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();

    this.renderer.setPixelRatio(this.getPixelRatio(this.currentQuality));
    this.renderer.setSize(width, height);
    this.postProcessing?.onResize(width, height);
  }

  /**
   * 动画循环
   */
  animate() {
    if (this.disposed) return;
    this.animationFrame = requestAnimationFrame(this._animate);

    const now = performance.now();
    const dt = Math.min((now - (this.lastFrameTime ?? now)) / 1000, 0.1);
    this.lastFrameTime = now;

    // 兜底：任何原因漏掉 resize 事件（微信/iOS 转屏）时，发现尺寸变了就立即校正
    const { width, height } = this.getViewportSize();
    if (this._lastSize !== `${width}x${height}`) this.onResize();

    // 更新控制器（含走路镜头起伏；motion = { speed, sprint, footstep }）
    if (this.settingsTourSession) this.settingsTourSession.updateControls();
    else this.controls.update();
    const motion = this.controls.motion ?? { speed: 0, sprint: false, footstep: false };

    // 更新位置信息
    this.updateLocationInfo();

    this.environment.update(this.camera, dt);
    this.palaceBuilder.update?.(dt);
    this.enclosure.update(dt);
    this.garden.update(dt);
    this.interiors?.update(this.camera.position);
    this.zoneManager.update({ x: this.camera.position.x, z: this.camera.position.z });
    this.ambience.update({
      dt,
      speed: motion.speed,
      sprint: motion.sprint,
      footstep: motion.footstep,
      inTunnel: this.isInGatePassage(this.camera.position),
    });
    this.minimap?.update(this.camera);
    if (now - this.lastShadowUpdate >= 250) {
      const distance = this.currentQuality === 'high' ? PERFORMANCE.LOD_DISTANCE_LOW : PERFORMANCE.LOD_DISTANCE_HIGH;
      this.shadowSetup.updateShadowLOD(this.camera, this.shadowObjects, distance);
      this.lastShadowUpdate = now;
    }
    this.postProcessing.render();
    this.perfHUD?.update(now);
  }

  dispose() {
    this.disposed = true;
    cancelAnimationFrame(this.animationFrame);
    clearTimeout(this.loadingTimeout);
    window.removeEventListener('resize', this._onResize);
    window.removeEventListener('orientationchange', this._onOrientationChange);
    window.visualViewport?.removeEventListener('resize', this._onResize);
    clearTimeout(this._resizeTimer1);
    clearTimeout(this._resizeTimer2);
    window.removeEventListener('touchstart', this._startAudio);
    window.removeEventListener('pointerdown', this._startAudio);
    if (this.controls) {
      this.controls.controls.removeEventListener('lock', this._onLock);
      this.controls.controls.removeEventListener('unlock', this._onUnlock);
      this.controls.controls.removeEventListener('lock', this._startAudio);
      this.controls.dispose();
    }
    this.ambience?.dispose();
    this.perfHUD?.dispose();
    this.minimap?.dispose();
    this.teleport?.dispose();
    window.removeEventListener('keydown', this._onTeleportKey);
    this.postProcessing?.dispose();
    this.palaceBuilder?.dispose();
    this.enclosure?.dispose();
    this.garden?.dispose();
    this.interiors?.dispose();
    this.zoneManager?.dispose();
    this.environment?.dispose();
    // 贴图库拥有共享材质与贴图，必须在所有使用方移除后最后释放
    this.library?.dispose();
    this.collisionManager?.clear();
    this.renderer?.dispose();
    this.renderer?.domElement.remove();
    for (const id of ['location-panel', 'help-panel']) document.getElementById(id)?.remove();
    this.settingsMenu?.dispose();
    this.minimap?.dispose();
    this.teleport?.dispose();
    window.removeEventListener('keydown', this._onTeleportKey);
    if (this._onKeyDown) window.removeEventListener('keydown', this._onKeyDown);
    this.shadowObjects.length = 0;
  }
}

// 本地开发暴露实例用于回归测试；生产页面不增加调试入口。
const app = new ForbiddenCityApp();
if (import.meta.env?.DEV) window.__forbiddenCityApp = app;
// 性能读数只读钩子（tests/perf.cjs 使用）：返回最近一个完整帧的快照副本
if (import.meta.env?.DEV) window.__perf = () => app.perfHUD?.snapshot() ?? null;
app.init().catch(error => console.error('故宫 3D 初始化失败', error));
if (import.meta.hot) import.meta.hot.dispose(() => app.dispose());

import * as THREE from 'three';
import { PointerLockControls } from 'three/examples/jsm/controls/PointerLockControls.js';
import { PLAYER } from '../config/constants.js';
import { VirtualJoystick } from './VirtualJoystick.js';

/**
 * 第一人称控制器
 * 支持桌面端（WASD + 鼠标）和移动端（虚拟摇杆 + 右半屏拖动视角）
 *
 * 说明（three r162）：PointerLockControls.getObject() 直接返回相机本身，
 * 移动使用 moveForward / moveRight，保证只在水平面（XZ）上移动，不受俯仰角影响。
 */

const _euler = new THREE.Euler(0, 0, 0, 'YXZ');
const _right = new THREE.Vector3();

// 走路镜头起伏参数：步频（步/秒）在参考速度下取值，随实际速度按平方根缩放
const HEAD_BOB = {
  WALK_AMPLITUDE: 0.035,        // 走路上下振幅（米）
  SPRINT_AMPLITUDE: 0.055,      // 冲刺上下振幅（米）
  SWAY_AMPLITUDE: 0.012,        // 左右横摆振幅（米），频率为上下的一半
  WALK_STEP_RATE: 1.8,          // 走路步频（步/秒，对应 PLAYER.MOVE_SPEED）
  SPRINT_STEP_RATE: 2.4,        // 冲刺步频（步/秒，对应 PLAYER.SPRINT_SPEED）
  MIN_STEP_SPEED: 0.5,          // 低于此速度不计脚步
  SMOOTHING: 8,                 // 振幅平滑系数（起步/停步回落）
};

export class FirstPersonControls {
  constructor(camera, domElement, collisionManager) {
    this.camera = camera;
    this.domElement = domElement;
    this.collisionManager = collisionManager;

    // 移动状态
    this.moveForward = false;
    this.moveBackward = false;
    this.moveLeft = false;
    this.moveRight = false;
    this.canSprint = false;
    this.pressedKeys = new Set();
    this.keyPressTimes = new Map(); // 记录每个方向键的按下时间
    this.lookLocked = false;
    this.lookTouchId = null;
    this.lookLockButton = null;
    // 移动端奔跑判定：记录当前推的方向和开始时间
    this.runDirAngle = null;
    this.runStartTime = 0;
    this.mobileRunning = false;
    this.runSessionGeneration = null;

    // 当前速度（x = 右移速度，z = 前进速度，单位：米/秒）
    this.velocity = new THREE.Vector3();
    // 脚面高度与竖直速度：相机 y = feetY + PLAYER.HEIGHT；上台阶平滑跟随，下落按重力
    this.feetY = 0;
    this.verticalVelocity = 0;
    // 空中状态（跳跃或从高处走下）：空中按真实脚面做碰撞，可越过矮栏杆；落地后恢复贴地
    this.airborne = false;
    this.jumpQueued = false;
    this.jumpButton = null;
    this._landed = false;

    // 镜头起伏：bobOffset 是上一帧叠加在相机上的偏移，下一帧开始时先扣除，碰撞只用无偏移的位置
    this.headBobEnabled = true;
    this.bobOffset = new THREE.Vector3();
    this.bobPhase = 0;          // 步频相位（单位：步），每跨过一个整数落一次脚
    this.bobAmplitude = 0;      // 平滑后的当前振幅
    // 每帧输出给音效：水平实际速度（米/秒）、是否冲刺、本帧是否落脚
    this.motion = { speed: 0, sprint: false, footstep: false };

    // 检测设备类型
    this.isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ||
      (/Macintosh/i.test(navigator.userAgent) && navigator.maxTouchPoints > 1);

    // 指针锁定控制
    this.controls = new PointerLockControls(camera, domElement);

    // 虚拟摇杆（移动端）
    this.joystick = null;
    if (this.isMobile) {
      this.joystick = new VirtualJoystick(domElement);
    }

    this.prevTime = performance.now();

    // 绑定 this，便于 dispose 时移除监听
    this._onKeyDown = this.onKeyDown.bind(this);
    this._onKeyUp = this.onKeyUp.bind(this);
    this._onStop = this.stop.bind(this);
    // 解锁（Esc / 打开地图）时清空输入；地图打开时（freeMove）保留，让玩家能边看地图边走
    this._onUnlockStop = () => { if (!this.freeMove) this.stop(); };
    // freeMove：不依赖指针锁定也接受键盘移动（打开地图时使用）
    this.freeMove = false;
    this._turnAxis = new THREE.Vector3(0, 1, 0);

    this.setupEventListeners();
  }

  /**
   * 设置事件监听
   */
  setupEventListeners() {
    window.addEventListener('blur', this._onStop);
    if (!this.isMobile) {
      // 点击启动指针锁定（桌面端）；点在按钮上不触发
      this._onClick = (e) => {
        if (e.target?.closest?.('button, a, input, select, textarea, [role="button"]')) return;
        if (!this.controls.isLocked) {
          this.controls.lock();
        }
      };
      this.domElement.addEventListener('click', this._onClick);

      // 键盘事件
      document.addEventListener('keydown', this._onKeyDown);
      document.addEventListener('keyup', this._onKeyUp);

      // 解锁时立即清空输入和速度
      this.controls.addEventListener('unlock', this._onUnlockStop);
    } else {
      // 移动端：视角锁定按钮 + 右半屏拖动视角 + 跳跃按钮
      this.createLookLockButton();
      this.createJumpButton();
    }
  }

  /** 请求起跳（PC 空格 / 移动端"跳"按钮），在下一帧 update 里执行 */
  jump() {
    this.jumpQueued = true;
  }

  /** 移动端右下角圆形"跳"按钮（在锁定视角按钮上方） */
  createJumpButton() {
    const btn = document.createElement('button');
    btn.className = 'jump-button';
    btn.textContent = '跳';
    btn.setAttribute('aria-label', '跳跃');
    btn.style.cssText = `
      position: fixed;
      right: calc(28px + env(safe-area-inset-right, 0px));
      bottom: calc(108px + env(safe-area-inset-bottom, 0px));
      width: 72px; height: 72px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.22);
      border: 2px solid rgba(255, 255, 255, 0.6);
      color: #fff; font-size: 22px; font-weight: bold;
      z-index: 1000;
      touch-action: none;
      -webkit-user-select: none; user-select: none;
      -webkit-tap-highlight-color: transparent;
    `;
    // touchstart 立即起跳（不等 click 的 300ms 延迟）；阻止冒泡，避免同时被当成"拖视角"
    this._onJumpTouch = (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.jump();
      btn.style.background = 'rgba(255, 215, 120, 0.45)';
      clearTimeout(this._jumpFlash);
      this._jumpFlash = setTimeout(() => { btn.style.background = 'rgba(255, 255, 255, 0.22)'; }, 160);
    };
    btn.addEventListener('touchstart', this._onJumpTouch, { passive: false });
    btn.addEventListener('click', () => this.jump());
    this.jumpButton = btn;
    this.domElement.appendChild(btn);
  }

  /**
   * 创建视角锁定按钮（移动端），并实现右半屏拖动视角
   */
  createLookLockButton() {
    const button = document.createElement('button');
    button.className = 'look-lock-button';
    button.textContent = '锁定视角';
    button.style.cssText = `
      position: fixed;
      bottom: calc(40px + env(safe-area-inset-bottom, 0px));
      right: calc(24px + env(safe-area-inset-right, 0px));
      padding: 12px 16px;
      background: rgba(255, 255, 255, 0.3);
      border: 2px solid rgba(255, 255, 255, 0.5);
      border-radius: 10px;
      color: white;
      font-size: 14px;
      z-index: 1000;
      cursor: pointer;
    `;

    this.lookLockButton = button;
    this._onLookLockClick = () => {
      this.lookLocked = !this.lookLocked;
      this.lookTouchId = null;
      button.textContent = this.lookLocked ? '解锁视角' : '锁定视角';
    };
    button.addEventListener('click', this._onLookLockClick);
    this.domElement.appendChild(button);

    // 用 touch.identifier 跟踪"看"的那根手指，避免和左侧摇杆手指互相干扰
    let lastX = 0;
    let lastY = 0;

    // 全屏任意位置拖动都可转视角，只排除：方向盘认领的手指、方向盘区域、按钮和浮层面板
    this._onLookTouchStart = (e) => {
      if (this.lookLocked || this.lookTouchId !== null) return;
      for (const touch of e.changedTouches) {
        if (this.joystick && (touch.identifier === this.joystick.touchId ||
            this.joystick.hitTest(touch.clientX, touch.clientY))) continue;
        if (!touch.target?.closest?.('button, a, input, select, textarea, [role="button"], #minimap, #minimap-preview, #settings-overlay, #settings-panel')) {
          this.lookTouchId = touch.identifier;
          lastX = touch.clientX;
          lastY = touch.clientY;
          break;
        }
      }
    };
    this.domElement.addEventListener('touchstart', this._onLookTouchStart, { passive: true });

    this._onLookTouchMove = (e) => {
      if (this.lookLocked || this.lookTouchId === null) return;
      for (const touch of e.changedTouches) {
        if (touch.identifier !== this.lookTouchId) continue;
        const deltaX = touch.clientX - lastX;
        const deltaY = touch.clientY - lastY;
        lastX = touch.clientX;
        lastY = touch.clientY;

        // 从相机当前朝向出发累加，避免第一次拖动时视角跳变
        _euler.setFromQuaternion(this.camera.quaternion);
        _euler.y -= deltaX * 0.005;
        _euler.x -= deltaY * 0.005;
        _euler.x = Math.max(-Math.PI / 2 + 0.01, Math.min(Math.PI / 2 - 0.01, _euler.x));
        this.camera.quaternion.setFromEuler(_euler);
      }
    };
    this.domElement.addEventListener('touchmove', this._onLookTouchMove, { passive: true });

    this._onLookTouchEnd = (e) => {
      for (const touch of e.changedTouches) {
        if (touch.identifier === this.lookTouchId) {
          this.lookTouchId = null;
        }
      }
    };
    this.domElement.addEventListener('touchend', this._onLookTouchEnd);
    this.domElement.addEventListener('touchcancel', this._onLookTouchEnd);
  }

  /**
   * 键盘按下
   */
  onKeyDown(event) {
    if (!this.controls.isLocked && !this.freeMove) return;
    const code = event.code;
    if (code === 'Space') {
      event.preventDefault();
      if (!event.repeat) this.jump();
      return;
    }
    // 记录方向键按下时间
    if (!this.pressedKeys.has(code) && this.isMovementKey(code)) {
      this.keyPressTimes.set(code, performance.now());
    }
    this.pressedKeys.add(code);
    this.updateKeyState();
  }

  /**
   * 键盘抬起
   */
  onKeyUp(event) {
    const code = event.code;
    this.pressedKeys.delete(code);
    this.keyPressTimes.delete(code);
    this.updateKeyState();
  }

  isMovementKey(code) {
    return code === 'KeyW' || code === 'KeyS' || code === 'KeyA' || code === 'KeyD' ||
           code === 'ArrowUp' || code === 'ArrowDown' || code === 'ArrowLeft' || code === 'ArrowRight';
  }

  updateKeyState() {
    const keys = this.pressedKeys;
    this.moveForward = keys.has('KeyW') || keys.has('ArrowUp');
    this.moveBackward = keys.has('KeyS') || keys.has('ArrowDown');
    this.moveLeft = keys.has('KeyA') || keys.has('ArrowLeft');
    this.moveRight = keys.has('KeyD') || keys.has('ArrowRight');
    // Shift 键仍然可以手动触发冲刺
    this.canSprint = keys.has('ShiftLeft') || keys.has('ShiftRight');
  }

  stop() {
    // 取消尚未消费的输入，不改已经起跳后的竖直速度或重力。
    this.jumpQueued = false;
    this.pressedKeys.clear();
    this.keyPressTimes.clear();
    this.updateKeyState();
    this.velocity.set(0, 0, 0);
    this.lookTouchId = null;
    if (this.joystick) this.joystick.reset();
  }

  /**
   * 每帧更新：计算目标速度 → 平滑插值 → 水平移动 → 碰撞修正
   */
  update() {
    const time = performance.now();
    // 限制最大步长，防止切后台回来时一帧"瞬移"穿墙
    const delta = Math.min((time - this.prevTime) / 1000, 0.1);
    this.prevTime = time;

    // 目标速度（前进 / 右移）
    let targetForward = 0;
    let targetRight = 0;

    // 桌面端：WASD
    if (!this.isMobile && (this.controls.isLocked || this.freeMove)) {
      // 地图打开、鼠标未锁定时用 Q/E 转向（锁定时用鼠标）
      if (this.freeMove && !this.controls.isLocked) {
        const turn = Number(this.pressedKeys.has('KeyQ')) - Number(this.pressedKeys.has('KeyE'));
        if (turn) this.camera.rotateOnWorldAxis(this._turnAxis, turn * 1.6 * delta);
      }
      let f = Number(this.moveForward) - Number(this.moveBackward);
      let r = Number(this.moveRight) - Number(this.moveLeft);
      const len = Math.hypot(f, r);
      if (len > 0) {
        f /= len;
        r /= len;
      }
      // 检查是否有方向键持续按下超过 2 秒，自动启用冲刺
      let autoSprint = false;
      const now = time;
      for (const [code, pressTime] of this.keyPressTimes) {
        if (now - pressTime >= 2000) { // 2 秒
          autoSprint = true;
          break;
        }
      }
      const sprint = this.canSprint || autoSprint;
      const speed = sprint ? PLAYER.SPRINT_SPEED : PLAYER.MOVE_SPEED;
      targetForward = f * speed;
      targetRight = r * speed;
    }

    // 移动端：摇杆（向上推 = 前进，屏幕坐标 y 向下为正，所以取反）
    // 持续朝同一方向推满 2 秒以上 → 奔跑；换方向、松手或推得太轻都会回到走路
    let mobileRunning = false;
    if (this.isMobile && this.joystick && this.joystick.isActive()) {
      // 松手/取消后可能在同一帧前重新认领，不能等 RAF 观察到 inactive。
      if (this.runSessionGeneration !== this.joystick.sessionGeneration) {
        this.runSessionGeneration = this.joystick.sessionGeneration;
        this.runDirAngle = null;
        this.runStartTime = 0;
      }
      const d = this.joystick.getDelta();
      const mag = Math.hypot(d.x, d.y);
      if (mag > 0.5) {
        const angle = Math.atan2(d.x, -d.y);
        let diff = 0;
        if (this.runDirAngle !== null) {
          diff = Math.abs(angle - this.runDirAngle);
          if (diff > Math.PI) diff = 2 * Math.PI - diff;
        }
        if (this.runDirAngle === null || diff > (PLAYER.JOYSTICK_RUN_ANGLE ?? 0.6)) {
          this.runDirAngle = angle;
          this.runStartTime = time;
        }
        mobileRunning = time - this.runStartTime >= (PLAYER.JOYSTICK_RUN_DELAY ?? 2000);
      } else {
        this.runDirAngle = null;
      }
      if (mobileRunning) {
        // 奔跑时按满速，方向取当前推的方向
        targetForward = (-d.y / mag) * PLAYER.JOYSTICK_RUN_SPEED;
        targetRight = (d.x / mag) * PLAYER.JOYSTICK_RUN_SPEED;
      } else {
        targetForward = -d.y * PLAYER.JOYSTICK_SPEED;
        targetRight = d.x * PLAYER.JOYSTICK_SPEED;
      }
    } else {
      this.runDirAngle = null;
    }
    if (this.joystick && this.mobileRunning !== mobileRunning) this.joystick.setRunning(mobileRunning);
    this.mobileRunning = mobileRunning;

    // 速度平滑（指数插值，起步/停步更自然）
    const smoothing = 1 - Math.exp(-10 * delta);
    this.velocity.z += (targetForward - this.velocity.z) * smoothing;
    this.velocity.x += (targetRight - this.velocity.x) * smoothing;

    // 先去掉上一帧的镜头起伏偏移，碰撞只用无偏移的位置，避免累积漂移
    this.camera.position.sub(this.bobOffset);
    this.bobOffset.set(0, 0, 0);

    // 起跳：只有站在地面上才能跳（空中不能二段跳）
    this._landed = false;
    if (this.jumpQueued) {
      this.jumpQueued = false;
      const onGround = !this.airborne && this.feetY >= (this.groundY ?? 0) - 0.08;
      if (onGround) {
        this.airborne = true;
        this.verticalVelocity = PLAYER.JUMP_VELOCITY ?? 6.7;
        this.groundY = this.feetY;
      }
    }
    const air = this.airborne;

    let speed = 0;
    // 空中：碰撞按真实脚面（可越过矮栏杆）；地面：按逻辑地面（上楼梯不滞后）
    const baseFeet = air ? this.feetY : Math.max(this.feetY, this.groundY ?? 0);
    const eyeY = baseFeet + PLAYER.HEIGHT;
    this._trackedGround = null;
    // 速度很小时直接归零，避免无意义的碰撞计算
    if (Math.abs(this.velocity.z) < 0.01 && Math.abs(this.velocity.x) < 0.01) {
      this.velocity.set(0, 0, 0);
    } else {
      const currentPosition = this.camera.position.clone();
      currentPosition.y = eyeY;

      // 只在水平面移动
      // PointerLockControls 读 local matrix；鼠标/触摸及本帧 Q/E 先更新的是 quaternion。
      this.camera.updateMatrix();
      this.controls.moveForward(this.velocity.z * delta);
      this.controls.moveRight(this.velocity.x * delta);

      // 碰撞检测（带沿墙滑动），用当前脚面高度对应的视点高度
      const newPosition = this.camera.position.clone();
      newPosition.y = eyeY;
      // 逐小步贴合地面（传入脚面），低帧率/快走一帧跨度大时也能正常上下台阶
      const validPosition = this.collisionManager.getValidPosition(
        currentPosition,
        newPosition,
        0.5,
        air ? (this.groundY ?? 0) : baseFeet,
        PLAYER.STEP_UP ?? 0.6,
        (air || this.onSupport) ? this.feetY : null
      );
      this._trackedGround = this.collisionManager.lastGroundY ?? null;

      this.camera.position.copy(validPosition);

      // 碰撞修正后的实际水平速度
      if (delta > 0) {
        speed = Math.hypot(validPosition.x - currentPosition.x, validPosition.z - currentPosition.z) / delta;
      }
    }

    this.updateGround(delta);
    this.camera.position.y = this.feetY + PLAYER.HEIGHT;

    const sprint = this.isMobile
      ? mobileRunning && speed > PLAYER.MOVE_SPEED * 0.5
      : this.canSprint && speed > PLAYER.MOVE_SPEED * 0.5;
    // 空中不计脚步、不晃镜头；落地那一帧补一声脚步
    const footstep = this.updateHeadBob(delta, this.airborne ? 0 : speed) || this._landed;
    this.motion.speed = speed;
    this.motion.sprint = sprint;
    this.motion.footstep = footstep;
  }

  /**
   * 脚面高度跟随地面：上台阶/上坡平滑抬升；地面降低时按重力下落（走下台阶、从台基边缘下来）
   */
  updateGround(delta) {
    // 以"逻辑地面"（上一帧所站的面）为基准查询，避免上长楼梯时镜头平滑滞后超过可迈高度而误判掉落
    const base = Math.max(this.feetY, this.groundY ?? 0);
    // 本帧移动过：用移动过程中逐小步追踪得到的地面；否则在原地查询
    const walkY = this._trackedGround ?? this.collisionManager.getGroundHeight(
      this.camera.position.x, this.camera.position.z, this.airborne ? this.feetY : base, PLAYER.STEP_UP ?? 0.6
    );
    // 栏杆 / 家具 / 矮墙顶面也能站（只认脚下方的，不会"走上"高物体）
    const sup = this.collisionManager.supportHeight?.(
      this.camera.position.x, this.camera.position.z, this.feetY + 0.05
    ) ?? -Infinity;
    const groundY = Math.max(walkY, sup);
    this.onSupport = sup > walkY + 0.01;
    this.groundY = groundY;
    // 地面骤降（从台基边缘、栏杆上走下去）转入空中状态：按真实身体高度判碰撞，不会卡进栏杆
    if (!this.airborne && groundY < this.feetY - (PLAYER.STEP_UP ?? 0.6)) {
      this.airborne = true;
      this.verticalVelocity = 0;
    }
    if (this.airborne) {
      // 跳到略高于脚面的台面上：脚面抬到台面，不陷进去
      if (this.feetY < groundY) {
        this.feetY = groundY;
        if (this.verticalVelocity <= 0) {
          this.verticalVelocity = 0;
          this.airborne = false;
          this._landed = true;
          return;
        }
      }
      // 跳跃中：竖直速度受重力，下落到脚下地面即落地
      const g = PLAYER.GRAVITY ?? 14;
      this.verticalVelocity = Math.max(this.verticalVelocity - g * delta, -(PLAYER.MAX_FALL_SPEED ?? 30));
      this.feetY += this.verticalVelocity * delta;
      if (this.verticalVelocity <= 0 && this.feetY <= groundY) {
        this.feetY = groundY;
        this.verticalVelocity = 0;
        this.airborne = false;
        this._landed = true;
      }
      return;
    }
    if (groundY >= this.feetY - 0.02) {
      // 上行或贴地：快速平滑跟随，避免台阶处抖动
      this.verticalVelocity = 0;
      const follow = 1 - Math.exp(-14 * delta);
      this.feetY += (groundY - this.feetY) * follow;
      if (Math.abs(groundY - this.feetY) < 0.005) this.feetY = groundY;
    } else {
      // 下落：重力加速，落到地面即停
      this.verticalVelocity = Math.max(this.verticalVelocity - 9.8 * delta, -12);
      this.feetY += this.verticalVelocity * delta;
      if (this.feetY <= groundY) {
        this.feetY = groundY;
        this.verticalVelocity = 0;
      }
    }
  }

  /**
   * 推进步频相位并把起伏偏移叠加到相机上；返回本帧是否落脚
   */
  updateHeadBob(delta, speed) {
    const walking = speed >= HEAD_BOB.MIN_STEP_SPEED;

    // 步频：0~走路速度按平方根缩放，走路~冲刺速度之间线性过渡，超出部分再按平方根缩放
    let stepRate = 0;
    if (walking) {
      if (speed <= PLAYER.MOVE_SPEED) {
        stepRate = HEAD_BOB.WALK_STEP_RATE * Math.sqrt(speed / PLAYER.MOVE_SPEED);
      } else if (speed <= PLAYER.SPRINT_SPEED) {
        const t = (speed - PLAYER.MOVE_SPEED) / (PLAYER.SPRINT_SPEED - PLAYER.MOVE_SPEED);
        stepRate = HEAD_BOB.WALK_STEP_RATE + (HEAD_BOB.SPRINT_STEP_RATE - HEAD_BOB.WALK_STEP_RATE) * t;
      } else {
        stepRate = HEAD_BOB.SPRINT_STEP_RATE * Math.sqrt(speed / PLAYER.SPRINT_SPEED);
      }
    }

    const prevPhase = this.bobPhase;
    this.bobPhase += stepRate * delta;
    const footstep = walking && Math.floor(this.bobPhase) > Math.floor(prevPhase);
    // 相位只关心小数部分与左右脚奇偶，定期回绕避免浮点精度损失
    if (this.bobPhase > 1000) this.bobPhase -= 1000;

    if (!this.headBobEnabled) {
      this.bobAmplitude = 0;
      return footstep;
    }

    // 目标振幅：慢走按速度比例减小，走路→冲刺之间插值；停下时平滑回落到 0
    let targetAmplitude = 0;
    if (walking) {
      const sprintMix = Math.min(Math.max((speed - PLAYER.MOVE_SPEED) / (PLAYER.SPRINT_SPEED - PLAYER.MOVE_SPEED), 0), 1);
      const base = HEAD_BOB.WALK_AMPLITUDE + (HEAD_BOB.SPRINT_AMPLITUDE - HEAD_BOB.WALK_AMPLITUDE) * sprintMix;
      targetAmplitude = base * Math.min(1, speed / PLAYER.MOVE_SPEED);
    }
    this.bobAmplitude += (targetAmplitude - this.bobAmplitude) * (1 - Math.exp(-HEAD_BOB.SMOOTHING * delta));
    if (targetAmplitude === 0 && this.bobAmplitude < 1e-4) this.bobAmplitude = 0;
    if (this.bobAmplitude === 0) return footstep;

    // 上下：每步一个周期，落脚（相位为整数）时处于最低点；左右：频率减半，沿相机水平右向量
    const k = this.bobAmplitude / HEAD_BOB.WALK_AMPLITUDE;
    const vertical = -this.bobAmplitude * Math.cos(2 * Math.PI * this.bobPhase);
    const sway = HEAD_BOB.SWAY_AMPLITUDE * Math.min(k, 1) * Math.cos(Math.PI * this.bobPhase);
    _right.set(1, 0, 0).applyQuaternion(this.camera.quaternion);
    _right.y = 0;
    if (_right.lengthSq() > 1e-8) _right.normalize();
    this.bobOffset.set(_right.x * sway, vertical, _right.z * sway);
    this.camera.position.add(this.bobOffset);
    return footstep;
  }

  /**
   * 开关镜头起伏（关闭时立即回到无偏移位置）
   */
  setHeadBob(enabled) {
    this.headBobEnabled = !!enabled;
    if (!this.headBobEnabled) {
      this.camera.position.sub(this.bobOffset);
      this.bobOffset.set(0, 0, 0);
      this.bobAmplitude = 0;
    }
  }

  /**
   * 获取控制器对象（即相机）
   */
  getObject() {
    return this.camera;
  }

  /**
   * 获取当前位置
   */
  getPosition() {
    return this.camera.position;
  }

  /**
   * 设置位置
   */
  setPosition(x, y, z) {
    this.camera.position.set(x, y, z);
    this.bobOffset.set(0, 0, 0);
    this.bobAmplitude = 0;
    // 传入的 y 视为视点高度；脚面取其下 PLAYER.HEIGHT，再贴合该处地面
    this.feetY = Math.max(0, y - PLAYER.HEIGHT);
    this.verticalVelocity = 0;
    this.airborne = false;
    this.onSupport = false;
    this.jumpQueued = false;
    if (this.collisionManager?.getGroundHeight) {
      this.feetY = this.collisionManager.getGroundHeight(x, z, this.feetY, PLAYER.STEP_UP ?? 0.6);
      this.camera.position.y = this.feetY + PLAYER.HEIGHT;
    }
    this.groundY = this.feetY;
  }

  /**
   * 当前脚面高度（米）
   */
  getFeetY() {
    return this.feetY;
  }

  /**
   * 让视线朝向某个点（只取水平方向，保持平视）
   */
  lookAt(x, z) {
    this.camera.lookAt(x, this.camera.position.y, z);
  }

  teleportTo(x, z, lookAtX, lookAtZ) {
    const ground = this.collisionManager.getGroundHeight(x, z, Infinity);
    this.stop();
    this.setPosition(x, ground + PLAYER.HEIGHT, z);
    this.lookAt(lookAtX, lookAtZ);
  }

  /**
   * 锁定指针
   */
  lock() {
    if (!this.isMobile) {
      this.controls.lock();
    }
  }

  /**
   * 解锁指针
   */
  unlock() {
    this.stop();
    if (!this.isMobile) {
      this.controls.unlock();
    }
  }

  /** 地图打开时：允许在未锁定指针的情况下继续用键盘移动 */
  setFreeMove(on) {
    this.freeMove = !!on;
    if (!on) this.stop();
  }

  /**
   * 检查是否锁定
   */
  isLocked() {
    return this.isMobile || this.controls.isLocked;
  }

  /**
   * 销毁
   */
  dispose() {
    this.stop();
    window.removeEventListener('blur', this._onStop);
    document.removeEventListener('keydown', this._onKeyDown);
    document.removeEventListener('keyup', this._onKeyUp);
    this.controls.removeEventListener('unlock', this._onUnlockStop);
    if (this._onClick) {
      this.domElement.removeEventListener('click', this._onClick);
    }
    if (this.lookLockButton) {
      this.domElement.removeEventListener('touchstart', this._onLookTouchStart);
      this.domElement.removeEventListener('touchmove', this._onLookTouchMove);
      this.domElement.removeEventListener('touchend', this._onLookTouchEnd);
      this.domElement.removeEventListener('touchcancel', this._onLookTouchEnd);
      this.lookLockButton.removeEventListener('click', this._onLookLockClick);
      this.lookLockButton.remove();
      this.lookLockButton = null;
    }
    if (this.jumpButton) {
      this.jumpButton.removeEventListener('touchstart', this._onJumpTouch);
      this.jumpButton.remove();
      this.jumpButton = null;
    }
    if (this.joystick) {
      this.joystick.dispose();
    }
    if (this.controls.isLocked) this.controls.unlock();
    this.controls.dispose();
  }
}

/**
 * 虚拟方向盘（移动端）
 * 常驻显示在左下角的半透明圆盘：按住圆盘拖动即可前后左右移动，松手归零。
 * 只认领落在圆盘附近的那根手指，其余手指留给视角拖动。
 */

const SIZE = 120;          // 底座直径（px）
const KNOB = 54;           // 摇杆头直径（px）
const HIT_PADDING = 45;    // 圆盘外扩的可触发范围（px），手指没按准也能用

export class VirtualJoystick {
  constructor(container) {
    this.container = container;
    this.active = false;
    this.baseX = 0;
    this.baseY = 0;
    this.stickX = 0;
    this.stickY = 0;
    this.deltaX = 0;
    this.deltaY = 0;
    this.touchId = null;
    // 每次认领都是新会话；touch.identifier 可复用，不能用它识别连续按住。
    this.sessionGeneration = 0;

    this.maxRadius = (SIZE - KNOB) / 2 + 10;

    this.createElements();
    this.bindEvents();
  }

  /**
   * 创建 DOM 元素（常驻显示）
   */
  createElements() {
    this.base = document.createElement('div');
    this.base.className = 'joystick-base';
    this.base.style.cssText = `
      position: fixed;
      left: calc(28px + env(safe-area-inset-left, 0px));
      bottom: calc(36px + env(safe-area-inset-bottom, 0px));
      width: ${SIZE}px;
      height: ${SIZE}px;
      background: radial-gradient(circle, rgba(255,255,255,0.10) 0%, rgba(255,255,255,0.22) 100%);
      border: 2px solid rgba(255, 255, 255, 0.45);
      border-radius: 50%;
      box-shadow: 0 2px 12px rgba(0, 0, 0, 0.25);
      z-index: 1000;
      pointer-events: none;
      transition: opacity 0.2s ease, background 0.2s ease;
      opacity: 0.75;
    `;

    // 上下左右方向箭头
    const arrows = [
      { ch: '▲', css: 'top: 6px; left: 50%; transform: translateX(-50%);' },
      { ch: '▼', css: 'bottom: 6px; left: 50%; transform: translateX(-50%);' },
      { ch: '◀', css: 'left: 8px; top: 50%; transform: translateY(-50%);' },
      { ch: '▶', css: 'right: 8px; top: 50%; transform: translateY(-50%);' },
    ];
    for (const a of arrows) {
      const el = document.createElement('span');
      el.textContent = a.ch;
      el.style.cssText = `position: absolute; ${a.css} font-size: 12px; line-height: 1; color: rgba(255,255,255,0.75); pointer-events: none;`;
      this.base.appendChild(el);
    }

    this.stick = document.createElement('div');
    this.stick.className = 'joystick-stick';
    this.stick.style.cssText = `
      position: absolute;
      top: 50%;
      left: 50%;
      width: ${KNOB}px;
      height: ${KNOB}px;
      background: rgba(255, 255, 255, 0.55);
      border: 2px solid rgba(255, 255, 255, 0.85);
      border-radius: 50%;
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
      transform: translate(-50%, -50%);
      pointer-events: none;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #7a4a00;
      font-size: 16px;
      font-weight: bold;
    `;

    this.base.appendChild(this.stick);
    this.container.appendChild(this.base);
  }

  bindEvents() {
    this._onTouchStart = this.onTouchStart.bind(this);
    this._onTouchMove = this.onTouchMove.bind(this);
    this._onTouchEnd = this.onTouchEnd.bind(this);
    this.container.addEventListener('touchstart', this._onTouchStart, { passive: false });
    this.container.addEventListener('touchmove', this._onTouchMove, { passive: false });
    this.container.addEventListener('touchend', this._onTouchEnd, { passive: false });
    this.container.addEventListener('touchcancel', this._onTouchEnd, { passive: false });
  }

  /**
   * 圆盘中心（屏幕坐标），每次按下时实时读取，兼容横竖屏切换
   */
  getCenter() {
    const r = this.base.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2, radius: r.width / 2 };
  }

  /**
   * 某个触点是否落在方向盘可触发范围内
   */
  hitTest(x, y) {
    const c = this.getCenter();
    return Math.hypot(x - c.x, y - c.y) <= c.radius + HIT_PADDING;
  }

  onTouchStart(e) {
    if (this.active) return;
    const touch = Array.from(e.changedTouches).find(t =>
      !t.target?.closest?.('button, a, input, select, textarea, [role="button"]') &&
      this.hitTest(t.clientX, t.clientY)
    );
    if (!touch) return;
    e.preventDefault();
    this.touchId = touch.identifier;
    this.sessionGeneration++;

    const c = this.getCenter();
    this.baseX = c.x;
    this.baseY = c.y;
    this.active = true;
    this.base.style.opacity = '1';
    this.base.style.background = 'radial-gradient(circle, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0.32) 100%)';
    this.updateStick(touch.clientX, touch.clientY);
  }

  onTouchMove(e) {
    if (!this.active) return;
    const touch = Array.from(e.changedTouches).find(t => t.identifier === this.touchId);
    if (!touch) return;
    e.preventDefault();
    this.updateStick(touch.clientX, touch.clientY);
  }

  updateStick(x, y) {
    const dx = x - this.baseX;
    const dy = y - this.baseY;
    const distance = Math.hypot(dx, dy);
    if (distance > this.maxRadius) {
      this.stickX = (dx / distance) * this.maxRadius;
      this.stickY = (dy / distance) * this.maxRadius;
    } else {
      this.stickX = dx;
      this.stickY = dy;
    }
    this.stick.style.transform = `translate(calc(-50% + ${this.stickX}px), calc(-50% + ${this.stickY}px))`;

    // 归一化偏移（-1 ~ 1），中心留一点死区，防止手指微抖导致漂移
    let nx = this.stickX / this.maxRadius;
    let ny = this.stickY / this.maxRadius;
    if (Math.hypot(nx, ny) < 0.12) { nx = 0; ny = 0; }
    this.deltaX = nx;
    this.deltaY = ny;
  }

  onTouchEnd(e) {
    const touch = Array.from(e.changedTouches).find(t => t.identifier === this.touchId);
    if (!touch) return;
    this.reset();
  }

  reset() {
    this.active = false;
    this.touchId = null;
    this.stickX = 0;
    this.stickY = 0;
    this.deltaX = 0;
    this.deltaY = 0;
    this.stick.style.transform = 'translate(-50%, -50%)';
    if (this.base) {
      this.base.style.opacity = '0.75';
      this.base.style.background = 'radial-gradient(circle, rgba(255,255,255,0.10) 0%, rgba(255,255,255,0.22) 100%)';
    }
  }

  /**
   * 奔跑状态：圆盘边框变金色并显示"跑"字提示
   */
  setRunning(running) {
    this.running = !!running;
    if (!this.base) return;
    this.base.style.borderColor = running ? 'rgba(255, 200, 60, 0.95)' : 'rgba(255, 255, 255, 0.45)';
    this.base.style.boxShadow = running
      ? '0 0 16px rgba(255, 200, 60, 0.7)'
      : '0 2px 12px rgba(0, 0, 0, 0.25)';
    this.stick.textContent = running ? '跑' : '';
  }

  getDelta() {
    return { x: this.deltaX, y: this.deltaY };
  }

  isActive() {
    return this.active;
  }

  dispose() {
    this.container.removeEventListener('touchstart', this._onTouchStart);
    this.container.removeEventListener('touchmove', this._onTouchMove);
    this.container.removeEventListener('touchend', this._onTouchEnd);
    this.container.removeEventListener('touchcancel', this._onTouchEnd);
    this.reset();
    if (this.base && this.base.parentNode) {
      this.base.parentNode.removeChild(this.base);
    }
  }
}

import * as THREE from 'three';
import { Environment } from './src/scene/Environment.js';
import { PalaceBuilder } from './src/scene/PalaceBuilder.js';
import { PALACE_LAYOUT } from './src/scene/Layout.js';
import { FirstPersonControls } from './src/controls/FirstPerson.js';
import { CollisionManager } from './src/utils/Collision.js';
import { PostProcessing } from './src/render/PostProcessing.js';
import { ShadowSetup } from './src/render/ShadowSetup.js';
import { TextureLibrary } from './src/utils/TextureLibrary.js';
import { Enclosure } from './src/scene/Enclosure.js';
import { GardenBuilder } from './src/scene/GardenBuilder.js';
import { ZoneManager } from './src/scene/zones/ZoneManager.js';
import { InteriorLoader } from './src/scene/interior/InteriorLoader.js';
import { ZONES } from './data/zones/index.js';
import { Ambience } from './src/audio/Ambience.js';
import { Minimap } from './src/ui/Minimap.js';
import { Teleport } from './src/ui/Teleport.js';
import { SettingsMenu } from './src/ui/SettingsMenu.js';
import { SettingsTourSession } from './src/ui/SettingsTourSession.js';
import { PerfHUD } from './src/ui/PerfHUD.js';
import { LAYOUT, PERFORMANCE, TELEPORT } from './src/config/constants.js';

/**
 * 故宫 3D 虚拟游览主程序
 */

class ForbiddenCityApp {
  constructor() {
    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.controls = null;
    this.postProcessing = null;
    this.collisionManager = null;

    this.currentQuality = 'high';
    this.isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ||
      (/Macintosh/i.test(navigator.userAgent) && navigator.maxTouchPoints > 1);
    this.lastLocation = null;
    this.lastShadowUpdate = 0;
    this.shadowObjects = [];
    this.disposed = false;
    this._animate = this.animate.bind(this);
    this._onResize = this.onResize.bind(this);

    // 加载管理
    this.loadingManager = new THREE.LoadingManager();
    this.loadingManager.onProgress = (url, loaded, total) => {
      const progress = (loaded / total) * 100;
      this.updateLoadingProgress(progress, url);
    };
    this.loadingManager.onLoad = () => {
      this.onLoadComplete();
    };
  }

  /**
   * 初始化
   */
  async init() {
    // 显示加载界面
    this.showLoading();

    // 尺寸监听必须在加载前注册：之前放在加载完成后，手机在加载过程中转横屏，
    // 画布会停留在竖屏尺寸，横屏时只占左半边、右边黑屏。
    // 微信 / iOS 转屏时 resize 可能不触发或触发时尺寸还没更新，所以再加 orientationchange、
    // visualViewport 两路兜底，并在转屏后延迟复查；动画循环里也会每帧比对尺寸。
    this._onOrientationChange = () => {
      this.onResize();
      clearTimeout(this._resizeTimer1);
      clearTimeout(this._resizeTimer2);
      this._resizeTimer1 = setTimeout(this._onResize, 200);
      this._resizeTimer2 = setTimeout(this._onResize, 600);
    };
    window.addEventListener('resize', this._onResize);
    window.addEventListener('orientationchange', this._onOrientationChange);
    window.visualViewport?.addEventListener('resize', this._onResize);

    // 说明：本项目的纹理（Canvas）和几何体都是程序化同步生成的，不经过任何 Loader，
    // LoadingManager 不会自动收到进度，onLoad 也不会触发（之前加载界面卡在 0% 的根因）。
    // 这里把每个构建步骤手动登记到 LoadingManager：先全部 itemStart，每完成一步 itemEnd，
    // 这样 onProgress 能正常推进进度条，最后一步完成时 onLoad 自动触发并关闭加载界面。
    const quality = this.isMobile ? 'low' : 'high';
    const steps = [
      ['渲染器', () => {
        this.createScene();
        this.createCamera();
        this.createRenderer();
        this.shadowSetup = new ShadowSetup(this.renderer);
        this.shadowSetup.init(quality);
      }],
      ['材质贴图', async () => {
        // 手机用 512 档贴图，桌面用 1024 档；加载失败的贴图自动回退为程序化贴图
        const maxAniso = this.renderer.capabilities.getMaxAnisotropy();
        this.library = new TextureLibrary({
          quality: this.isMobile ? 'sd' : 'hd',
          anisotropy: Math.min(maxAniso, this.isMobile ? 2 : 8),
        });
        const stepIndex = steps.findIndex(([name]) => name === '材质贴图');
        await this.library.load((done, total) => {
          const progress = ((stepIndex + done / Math.max(total, 1)) / steps.length) * 100;
          this.updateLoadingProgress(progress, `材质贴图 ${done}/${total}`);
        });
      }],
      ['天空与光照', () => {
        this.environment = new Environment(this.scene, this.renderer, this.library);
        this.environment.init();
        this.environment.setQuality(quality === 'high');
      }],
      ['宫殿建筑', () => {
        this.palaceBuilder = new PalaceBuilder(this.scene, this.library);
        this.palaceBuilder.buildAll(PALACE_LAYOUT);
      }],
      ['宫墙与庑房', () => {
        this.enclosure = new Enclosure(this.scene, this.library).build();
      }],
      ['御花园', () => {
        const garden = PALACE_LAYOUT.find(item => item.type === 'garden');
        this.garden = new GardenBuilder(this.scene, this.library).build(garden);
        // 静态场景（中轴/宫墙/御花园）进入阴影 LOD 列表；分区网格由 ZoneManager 回调增删
        this.scene.traverse(object => {
          if (object.isMesh) this.shadowObjects.push(object);
        });
      }],
      ['东西六宫与两路宫殿', () => {
        // 碰撞管理器先建：ZoneManager 加载区时要往里注册带 tag 的碰撞体
        this.collisionManager = new CollisionManager();
        this.zoneManager = new ZoneManager();
        this.zoneManager.onLoad = (_id, group) => group.traverse(o => { if (o.isMesh) this.shadowObjects.push(o); });
        this.zoneManager.onUnload = (_id, group) => {
          const gone = new Set();
          group.traverse(o => { if (o.isMesh) gone.add(o); });
          this.shadowObjects = this.shadowObjects.filter(o => !gone.has(o));
        };
        ZONES.forEach(zone => this.zoneManager.register(zone));
        const start = LAYOUT.START_POSITION;
        this.zoneManager.init(this.scene, this.library, this.collisionManager, { x: start.x, z: start.z });
      }],
      ['碰撞检测', () => {
        this.collisionManager.addColliders(this.palaceBuilder.getColliders());
        this.collisionManager.addWalkables(this.palaceBuilder.getWalkables());
        this.collisionManager.addColliders(this.enclosure.getColliders());
        this.collisionManager.addColliders(this.garden.getColliders());
        this.collisionManager.addWalkables(this.garden.getWalkables());
        // 分区的 colliders/walkables 由 ZoneManager 带 tag 注册/移除；regions 启动时已覆盖全部分区
        this.collisionManager.setRegions(this.zoneManager.getRegions());
        // 所有可进入房间（世界坐标，含门/掩体/刷怪点），后续玩法从这里取
        this.rooms = this.zoneManager.getRooms();
        // S 档内景：按距离流式加载 GLB（失败回退 B 档）
        // base：部署到子路径（如 GitHub Pages /forbidden-city-3d/）时，模型与 draco/basis 解码器都要带前缀；根路径部署时为 ''
        const base = (import.meta.env?.BASE_URL ?? '/').replace(/\/$/, '');
        this.interiors = new InteriorLoader(this.scene, this.collisionManager, { renderer: this.renderer, base });
      }],
      ['控制器', () => {
        this.controls = new FirstPersonControls(this.camera, document.body, this.collisionManager);
        const start = LAYOUT.START_POSITION;
        this.controls.setPosition(start.x, start.y, start.z);
        // 相机默认朝向 -Z（背对故宫），出生时转身面向北边的午门
        this.controls.lookAt(0, LAYOUT.WUMEN_Z);
        this.bindWelcomeOverlay();
      }],
      ['后期处理', () => {
        this.postProcessing = new PostProcessing(this.renderer, this.scene, this.camera);
        this.postProcessing.init(quality);
        this.currentQuality = quality;
      }],
      ['界面', () => {
        this.ambience = new Ambience();
        this.createUI();
        this.bindAudioStart();
        this.perfHUD = new PerfHUD(this.renderer, {
          zoneProvider: () => ({
            current: this.zoneManager?.getCurrentId() ?? '-',
            loaded: this.zoneManager?.getLoadedIds() ?? []
          })
        });
      }],
    ];

    steps.forEach(([name]) => this.loadingManager.itemStart(name));

    try {
      for (const [name, run] of steps) {
        await run();
        this.loadingManager.itemEnd(name);
        // 让出一帧，让浏览器把进度条刷新到屏幕上
        await new Promise(resolve => requestAnimationFrame(() => setTimeout(resolve, 0)));
        if (this.disposed) return;
      }
    } catch (err) {
      this.showLoadingError(err);
      throw err;
    }

    // 加载期间可能已经转过屏，进入渲染前按当前窗口尺寸校正一次
    this.onResize();

    // 开始动画循环
    this.animate();

    console.log('故宫 3D 初始化完成');
  }

  /**
   * 桌面端欢迎遮罩：加载完成后显示，点击锁定鼠标后隐藏，按 ESC 解锁后重新显示
   */
  bindWelcomeOverlay() {
    if (this.isMobile) return;
    const overlay = document.getElementById('welcome-overlay');
    if (!overlay) return;
    this._onLock = () => { overlay.style.display = 'none'; };
    this._onUnlock = () => { overlay.style.display = this.minimap?.visible || this.settingsMenu?.visible ? 'none' : 'flex'; };
    this.controls.controls.addEventListener('lock', this._onLock);
    this.controls.controls.addEventListener('unlock', this._onUnlock);
  }

  /**
   * 初始化出错时，在加载界面上直接显示错误，避免一直卡在进度条
   */
  showLoadingError(err) {
    const progressText = document.getElementById('progress-text');
    if (progressText) {
      progressText.style.color = '#ff6b6b';
      progressText.textContent = `加载失败：${err && err.message ? err.message : err}（详情见控制台）`;
    }
  }

  /**
   * 创建场景
   */
  createScene() {
    this.scene = new THREE.Scene();
  }

  /**
   * 创建相机
   */
  createCamera() {
    // 70° 视场更接近人眼观感；远裁剪面 2500 米：真实米制下宫城南北 961 m，从午门外要能看到神武门与天际线远景环
    this.camera = new THREE.PerspectiveCamera(
      70,
      window.innerWidth / window.innerHeight,
      0.1,
      2500
    );
  }

  /**
   * 创建渲染器
   */
  createRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      antialias: !this.isMobile,
      powerPreference: 'high-performance',
    });

    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(this.getPixelRatio(this.isMobile ? 'low' : 'high'));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    // 电影感色调映射：高光不过曝、红墙黄瓦饱和度自然
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 0.7; // 降低曝光，避免天空过亮

    // 画布必须放进 #scene-container 里：
    // 之前直接 append 到 body 末尾，而 #scene-container 已占满 100% 视口，
    // 画布被挤到可视区域下方（body overflow:hidden），所以加载完是一片黑屏
    const canvas = this.renderer.domElement;
    canvas.id = 'scene-canvas';
    const container = document.getElementById('scene-container') || document.body;
    container.appendChild(canvas);
  }

  /**
   * 创建 UI
   */
  createUI() {
    // 位置信息面板
    this.locationPanel = document.createElement('div');
    this.locationPanel.id = 'location-panel';
    this.locationPanel.style.cssText = `
      position: fixed;
      top: 20px;
      left: 20px;
      padding: 15px 20px;
      background: rgba(0, 0, 0, 0.6);
      color: white;
      border-radius: 8px;
      font-size: 16px;
      z-index: 1000;
      font-family: Arial, sans-serif;
    `;
    document.body.appendChild(this.locationPanel);

    // 操作说明面板
    const helpPanel = document.createElement('div');
    helpPanel.id = 'help-panel';
    helpPanel.style.cssText = `
      position: fixed;
      top: 80px;
      left: 20px;
      padding: 15px 20px;
      background: rgba(0, 0, 0, 0.6);
      color: white;
      border-radius: 8px;
      font-size: 14px;
      z-index: 1000;
      font-family: Arial, sans-serif;
      line-height: 1.6;
    `;

    if (this.isMobile) {
      helpPanel.innerHTML = `
        <strong>操作说明</strong><br>
        左下角方向盘：前后左右移动<br>
        同一方向推住2秒：跑起来<br>
        手指拖动屏幕：调整视角<br>
        右下角"跳"：跳过矮墙栏杆<br>
        右上角地图：点开看全图<br>
        右下角按钮：锁定视角<br>
        午门/神武门两端有马道可登城楼
      `;
      // 手机屏幕小，说明面板 8 秒后自动淡出，避免遮挡画面
      helpPanel.style.transition = 'opacity 0.6s ease';
      setTimeout(() => { helpPanel.style.opacity = '0'; }, 8000);
    } else {
      helpPanel.innerHTML = `
        <strong>操作说明</strong><br>
        WASD / 方向键：移动<br>
        长按2秒：自动快走<br>
        鼠标：视角<br>
        空格：跳跃<br>
        M键：小地图<br>
        午门/神武门两端马道可登城楼<br>
        点击屏幕开始游览
      `;
    }
    document.body.appendChild(helpPanel);

    // 小地图（按 M 键显示/隐藏）
    // 移动端额外常驻右上角预览，点击展开全图
    this.teleport = new Teleport(this.controls, this.zoneManager, this.collisionManager);
    this._onTeleportKey = event => {
      if (event.repeat || event.ctrlKey || event.metaKey || event.altKey || /^(INPUT|TEXTAREA|SELECT)$/.test(event.target?.tagName)) return;
      const index = Number(event.key) - 1;
      if (/^[1-8]$/.test(event.key)) this.teleport.go(TELEPORT.POINTS[index].target);
    };
    window.addEventListener('keydown', this._onTeleportKey);
    this.minimap = new Minimap({ items: this.zoneManager.getMapItems(), preview: this.isMobile, onTeleport: name => this.teleport.go(name), onToggle: visible => {
      this.settingsMenu?.setMapMode(visible, this.minimap.container);
      if (this.settingsTourSession?.paused) {
        this.settingsTourSession.mapChanged(visible);
        return;
      }
      // 打开地图：释放鼠标以便缩放/点击，但保留键盘移动（WASD 走动、Q/E 转向）；关闭：重新锁定视角
      this.controls.setFreeMove?.(visible);
      // unlock 事件会重新显示欢迎遮罩，先同步隐藏；之后的 unlock 回调也会检查 minimap.visible
      const overlay = document.getElementById('welcome-overlay');
      if (visible && overlay) overlay.style.display = 'none';
      if (visible) this.controls.unlock();
      else { try { this.controls.lock(); } catch { /* 需要用户手势时忽略，点击画面即可重新进入 */ } }
    } });

    // 设置菜单（按 ESC 显示）
    this.settingsTourSession = new SettingsTourSession({
      controls: this.controls,
      isMobile: this.isMobile,
      minimap: this.minimap,
      welcomeOverlay: document.getElementById('welcome-overlay'),
    });
    this.settingsMenu = new SettingsMenu(document.body);
    this.settingsMenu.init({
      initialQuality: this.currentQuality,
      initialSound: true,
      onOpen: () => this.settingsTourSession.open(),
      onResume: () => this.settingsTourSession.resume(),
      onQualityChange: (quality) => {
        this.toggleQuality(quality);
      },
      onSoundToggle: (enabled) => {
        if (!enabled) {
          this.ambience.setMuted(true);
        } else {
          this.ambience.start();
          this.ambience.setMuted(false);
        }
      },
    });

    // 绑定 ESC 键打开设置菜单
    this._onKeyDown = (event) => {
      if (event.code === 'Escape' && !event.repeat) {
        event.preventDefault();
        this.settingsMenu.toggle();
      }
    };
    window.addEventListener('keydown', this._onKeyDown);
  }

  /** 浏览器要求用户手势后才能启动音频：桌面锁定鼠标时、移动端首次触摸时启动 */
  bindAudioStart() {
    this._startAudio = () => this.ambience?.start();
    this.controls.controls.addEventListener('lock', this._startAudio);
    window.addEventListener('touchstart', this._startAudio, { passive: true });
    window.addEventListener('pointerdown', this._startAudio);
  }

  /** 是否位于某座门楼的门洞内（用于音效混响） */
  isInGatePassage(position) {
    return PALACE_LAYOUT.some(item => item.type === 'gate' &&
      Math.abs(position.x - item.position.x) < item.dimensions.width * 0.075 &&
      Math.abs(position.z - item.position.z) < item.dimensions.depth / 2);
  }

  /**
   * 切换画质
   */
  getPixelRatio(quality) {
    const cap = quality === 'low' ? 1 : (this.isMobile ? PERFORMANCE.MOBILE_MAX_PIXEL_RATIO : 2);
    return Math.min(window.devicePixelRatio || 1, cap);
  }

  toggleQuality(quality = this.currentQuality === 'high' ? 'low' : 'high') {
    // The menu supplies the chosen value. Do not invert it a second time.
    // No-argument calls still toggle for keyboard/testing callers.
    if (quality !== 'high' && quality !== 'low') throw new Error(`Unsupported quality: ${quality}`);
    this.currentQuality = quality;

    // 更新渲染设置
    this.renderer.setPixelRatio(this.getPixelRatio(this.currentQuality));
    this.postProcessing.setQuality(this.currentQuality);
    this.environment.setQuality(this.currentQuality === 'high');
    this.shadowSetup.setQuality(this.currentQuality);
    this.lastShadowUpdate = 0;
    if (this.settingsMenu) {
      this.settingsMenu.currentQuality = this.currentQuality;
      this.settingsMenu.updateQualityButton();
    }
  }

  /**
   * 更新位置信息
   */
  updateLocationInfo() {
    const position = this.controls.getPosition();
    const location = this.collisionManager.getCurrentLocation(position);
    const zone = ZONES.find(item => item.id === this.zoneManager.getCurrentId())?.name ?? '宫城';
    const label = `${zone} › ${location}`;
    if (label === this.lastLocation) return;
    this.lastLocation = label;
    this.locationPanel.replaceChildren();
    const heading = document.createElement('strong');
    heading.textContent = '当前位置';
    this.locationPanel.append(heading, document.createElement('br'), document.createTextNode(label));
  }

  /**
   * 显示加载界面
   */
  showLoading() {
    const loading = document.getElementById('loading-screen');
    if (loading) {
      loading.style.display = 'flex';
    }
  }

  /**
   * 更新加载进度
   */
  updateLoadingProgress(progress, stepName = '') {
    const progressBar = document.getElementById('progress-bar');
    const progressText = document.getElementById('progress-text');

    if (progressBar) {
      progressBar.style.width = `${progress}%`;
    }
    if (progressText) {
      const suffix = stepName ? (stepName.includes('/') ? `（${stepName}）` : `（${stepName}已完成）`) : '';
      progressText.textContent = `加载中... ${Math.round(progress)}%${suffix}`;
    }
  }

  /**
   * 加载完成
   */
  onLoadComplete() {
    this.loadingTimeout = setTimeout(() => {
      if (this.disposed) return;
      const loading = document.getElementById('loading-screen');
      if (loading) {
        loading.style.display = 'none';
      }

      // 移动端自动开始，桌面端显示欢迎遮罩，点击后锁定鼠标开始游览
      if (this.isMobile) {
        console.log('移动端自动开始');
      } else {
        const overlay = document.getElementById('welcome-overlay');
        if (overlay && !this.controls.controls.isLocked) {
          overlay.style.display = 'flex';
        }
        console.log('点击屏幕开始游览');
      }
    }, 500);
  }

  /**
   * 窗口大小调整
   */
  getViewportSize() {
    // 以布局视口为准；部分安卓 WebView 转屏后 innerWidth 更新滞后，取 documentElement 兜底
    const width = Math.max(1, Math.round(window.innerWidth || document.documentElement.clientWidth));
    const height = Math.max(1, Math.round(window.innerHeight || document.documentElement.clientHeight));
    return { width, height };
  }

  onResize() {
    if (this.disposed || !this.camera || !this.renderer) return;
    const { width, height } = this.getViewportSize();
    this._lastSize = `${width}x${height}`;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();

    this.renderer.setPixelRatio(this.getPixelRatio(this.currentQuality));
    this.renderer.setSize(width, height);
    this.postProcessing?.onResize(width, height);
  }

  /**
   * 动画循环
   */
  animate() {
    if (this.disposed) return;
    this.animationFrame = requestAnimationFrame(this._animate);

    const now = performance.now();
    const dt = Math.min((now - (this.lastFrameTime ?? now)) / 1000, 0.1);
    this.lastFrameTime = now;

    // 兜底：任何原因漏掉 resize 事件（微信/iOS 转屏）时，发现尺寸变了就立即校正
    const { width, height } = this.getViewportSize();
    if (this._lastSize !== `${width}x${height}`) this.onResize();

    // 更新控制器（含走路镜头起伏；motion = { speed, sprint, footstep }）
    if (this.settingsTourSession) this.settingsTourSession.updateControls();
    else this.controls.update();
    const motion = this.controls.motion ?? { speed: 0, sprint: false, footstep: false };

    // 更新位置信息
    this.updateLocationInfo();

    this.environment.update(this.camera, dt);
    this.palaceBuilder.update?.(dt);
    this.enclosure.update(dt);
    this.garden.update(dt);
    this.interiors?.update(this.camera.position);
    this.zoneManager.update({ x: this.camera.position.x, z: this.camera.position.z });
    this.ambience.update({
      dt,
      speed: motion.speed,
      sprint: motion.sprint,
      footstep: motion.footstep,
      inTunnel: this.isInGatePassage(this.camera.position),
    });
    this.minimap?.update(this.camera);
    if (now - this.lastShadowUpdate >= 250) {
      const distance = this.currentQuality === 'high' ? PERFORMANCE.LOD_DISTANCE_LOW : PERFORMANCE.LOD_DISTANCE_HIGH;
      this.shadowSetup.updateShadowLOD(this.camera, this.shadowObjects, distance);
      this.lastShadowUpdate = now;
    }
    this.postProcessing.render();
    this.perfHUD?.update(now);
  }

  dispose() {
    this.disposed = true;
    cancelAnimationFrame(this.animationFrame);
    clearTimeout(this.loadingTimeout);
    window.removeEventListener('resize', this._onResize);
    window.removeEventListener('orientationchange', this._onOrientationChange);
    window.visualViewport?.removeEventListener('resize', this._onResize);
    clearTimeout(this._resizeTimer1);
    clearTimeout(this._resizeTimer2);
    window.removeEventListener('touchstart', this._startAudio);
    window.removeEventListener('pointerdown', this._startAudio);
    if (this.controls) {
      this.controls.controls.removeEventListener('lock', this._onLock);
      this.controls.controls.removeEventListener('unlock', this._onUnlock);
      this.controls.controls.removeEventListener('lock', this._startAudio);
      this.controls.dispose();
    }
    this.ambience?.dispose();
    this.perfHUD?.dispose();
    this.minimap?.dispose();
    this.teleport?.dispose();
    window.removeEventListener('keydown', this._onTeleportKey);
    this.postProcessing?.dispose();
    this.palaceBuilder?.dispose();
    this.enclosure?.dispose();
    this.garden?.dispose();
    this.interiors?.dispose();
    this.zoneManager?.dispose();
    this.environment?.dispose();
    // 贴图库拥有共享材质与贴图，必须在所有使用方移除后最后释放
    this.library?.dispose();
    this.collisionManager?.clear();
    this.renderer?.dispose();
    this.renderer?.domElement.remove();
    for (const id of ['location-panel', 'help-panel']) document.getElementById(id)?.remove();
    this.settingsMenu?.dispose();
    this.minimap?.dispose();
    this.teleport?.dispose();
    window.removeEventListener('keydown', this._onTeleportKey);
    if (this._onKeyDown) window.removeEventListener('keydown', this._onKeyDown);
    this.shadowObjects.length = 0;
  }
}

