  },
  LOW: {
    shadowMapSize: 512,
    enableSSAO: false,
    enableBloom: false,
    antialias: false,
  },
};

import * as THREE from 'three';
import { PointerLockControls } from 'three/examples/jsm/controls/PointerLockControls.js';
import { PLAYER } from '../config/constants.js';
import { VirtualJoystick } from './VirtualJoystick.js';

/**
 * 第一人称控制器
 * 支持桌面端（WASD + 鼠标）和移动端（虚拟摇杆 + 右半屏拖动视角）
 *
 * 说明（three r162）：PointerLockControls.getObject() 直接返回相机本身，
 * 移动使用 moveForward / moveRight，保证只在水平面（XZ）上移动，不受俯仰角影响。
 */

const _euler = new THREE.Euler(0, 0, 0, 'YXZ');
const _right = new THREE.Vector3();

// 走路镜头起伏参数：步频（步/秒）在参考速度下取值，随实际速度按平方根缩放
const HEAD_BOB = {
  WALK_AMPLITUDE: 0.035,        // 走路上下振幅（米）
  SPRINT_AMPLITUDE: 0.055,      // 冲刺上下振幅（米）
  SWAY_AMPLITUDE: 0.012,        // 左右横摆振幅（米），频率为上下的一半
  WALK_STEP_RATE: 1.8,          // 走路步频（步/秒，对应 PLAYER.MOVE_SPEED）
  SPRINT_STEP_RATE: 2.4,        // 冲刺步频（步/秒，对应 PLAYER.SPRINT_SPEED）
  MIN_STEP_SPEED: 0.5,          // 低于此速度不计脚步
  SMOOTHING: 8,                 // 振幅平滑系数（起步/停步回落）
};

export class FirstPersonControls {
  constructor(camera, domElement, collisionManager) {
    this.camera = camera;
    this.domElement = domElement;
    this.collisionManager = collisionManager;

    // 移动状态
    this.moveForward = false;
    this.moveBackward = false;
    this.moveLeft = false;
    this.moveRight = false;
    this.canSprint = false;
    this.pressedKeys = new Set();
    this.keyPressTimes = new Map(); // 记录每个方向键的按下时间
    this.lookLocked = false;
    this.lookTouchId = null;
    this.lookLockButton = null;
    // 移动端奔跑判定：记录当前推的方向和开始时间
    this.runDirAngle = null;
    this.runStartTime = 0;
    this.mobileRunning = false;

    // 当前速度（x = 右移速度，z = 前进速度，单位：米/秒）
    this.velocity = new THREE.Vector3();
    // 脚面高度与竖直速度：相机 y = feetY + PLAYER.HEIGHT；上台阶平滑跟随，下落按重力
    this.feetY = 0;
    this.verticalVelocity = 0;
    // 空中状态（跳跃或从高处走下）：空中按真实脚面做碰撞，可越过矮栏杆；落地后恢复贴地
    this.airborne = false;
    this.jumpQueued = false;
    this.jumpButton = null;
    this._landed = false;

    // 镜头起伏：bobOffset 是上一帧叠加在相机上的偏移，下一帧开始时先扣除，碰撞只用无偏移的位置
    this.headBobEnabled = true;
    this.bobOffset = new THREE.Vector3();
    this.bobPhase = 0;          // 步频相位（单位：步），每跨过一个整数落一次脚
    this.bobAmplitude = 0;      // 平滑后的当前振幅
    // 每帧输出给音效：水平实际速度（米/秒）、是否冲刺、本帧是否落脚
    this.motion = { speed: 0, sprint: false, footstep: false };

    // 检测设备类型
    this.isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ||
      (/Macintosh/i.test(navigator.userAgent) && navigator.maxTouchPoints > 1);

    // 指针锁定控制
    this.controls = new PointerLockControls(camera, domElement);

    // 虚拟摇杆（移动端）
    this.joystick = null;
    if (this.isMobile) {
      this.joystick = new VirtualJoystick(domElement);
    }

    this.prevTime = performance.now();

    // 绑定 this，便于 dispose 时移除监听
    this._onKeyDown = this.onKeyDown.bind(this);
    this._onKeyUp = this.onKeyUp.bind(this);
    this._onStop = this.stop.bind(this);
    // 解锁（Esc / 打开地图）时清空输入；地图打开时（freeMove）保留，让玩家能边看地图边走
    this._onUnlockStop = () => { if (!this.freeMove) this.stop(); };
    // freeMove：不依赖指针锁定也接受键盘移动（打开地图时使用）
    this.freeMove = false;
    this._turnAxis = new THREE.Vector3(0, 1, 0);

    this.setupEventListeners();
  }

  /**
   * 设置事件监听
   */
  setupEventListeners() {
    window.addEventListener('blur', this._onStop);
    if (!this.isMobile) {
      // 点击启动指针锁定（桌面端）；点在按钮上不触发
      this._onClick = (e) => {
        if (e.target?.closest?.('button, a, input, select, textarea, [role="button"]')) return;
        if (!this.controls.isLocked) {
          this.controls.lock();
        }
      };
      this.domElement.addEventListener('click', this._onClick);

      // 键盘事件
      document.addEventListener('keydown', this._onKeyDown);
      document.addEventListener('keyup', this._onKeyUp);

      // 解锁时立即清空输入和速度
      this.controls.addEventListener('unlock', this._onUnlockStop);
    } else {
      // 移动端：视角锁定按钮 + 右半屏拖动视角 + 跳跃按钮
      this.createLookLockButton();
      this.createJumpButton();
    }
  }

  /** 请求起跳（PC 空格 / 移动端"跳"按钮），在下一帧 update 里执行 */
  jump() {
    this.jumpQueued = true;
  }

  /** 移动端右下角圆形"跳"按钮（在锁定视角按钮上方） */
  createJumpButton() {
    const btn = document.createElement('button');
    btn.className = 'jump-button';
    btn.textContent = '跳';
    btn.setAttribute('aria-label', '跳跃');
    btn.style.cssText = `
      position: fixed;
      right: calc(28px + env(safe-area-inset-right, 0px));
      bottom: calc(108px + env(safe-area-inset-bottom, 0px));
      width: 72px; height: 72px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.22);
      border: 2px solid rgba(255, 255, 255, 0.6);
      color: #fff; font-size: 22px; font-weight: bold;
      z-index: 1000;
      touch-action: none;
      -webkit-user-select: none; user-select: none;
      -webkit-tap-highlight-color: transparent;
    `;
    // touchstart 立即起跳（不等 click 的 300ms 延迟）；阻止冒泡，避免同时被当成"拖视角"
    this._onJumpTouch = (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.jump();
      btn.style.background = 'rgba(255, 215, 120, 0.45)';
      clearTimeout(this._jumpFlash);
      this._jumpFlash = setTimeout(() => { btn.style.background = 'rgba(255, 255, 255, 0.22)'; }, 160);
    };
    btn.addEventListener('touchstart', this._onJumpTouch, { passive: false });
    btn.addEventListener('click', () => this.jump());
    this.jumpButton = btn;
    this.domElement.appendChild(btn);
  }

  /**
   * 创建视角锁定按钮（移动端），并实现右半屏拖动视角
   */
  createLookLockButton() {
    const button = document.createElement('button');
    button.className = 'look-lock-button';
    button.textContent = '锁定视角';
    button.style.cssText = `
      position: fixed;
      bottom: calc(40px + env(safe-area-inset-bottom, 0px));
      right: calc(24px + env(safe-area-inset-right, 0px));
      padding: 12px 16px;
      background: rgba(255, 255, 255, 0.3);
      border: 2px solid rgba(255, 255, 255, 0.5);
      border-radius: 10px;
      color: white;
      font-size: 14px;
      z-index: 1000;
      cursor: pointer;
    `;

    this.lookLockButton = button;
    this._onLookLockClick = () => {
      this.lookLocked = !this.lookLocked;
      this.lookTouchId = null;
      button.textContent = this.lookLocked ? '解锁视角' : '锁定视角';
    };
    button.addEventListener('click', this._onLookLockClick);
    this.domElement.appendChild(button);

    // 用 touch.identifier 跟踪"看"的那根手指，避免和左侧摇杆手指互相干扰
    let lastX = 0;
    let lastY = 0;

    // 全屏任意位置拖动都可转视角，只排除：方向盘认领的手指、方向盘区域、按钮和浮层面板
    this._onLookTouchStart = (e) => {
      if (this.lookLocked || this.lookTouchId !== null) return;
      for (const touch of e.changedTouches) {
        if (this.joystick && (touch.identifier === this.joystick.touchId ||
            this.joystick.hitTest(touch.clientX, touch.clientY))) continue;
        if (!touch.target?.closest?.('button, a, input, select, textarea, [role="button"], #minimap, #minimap-preview, #settings-overlay, #settings-panel')) {
          this.lookTouchId = touch.identifier;
          lastX = touch.clientX;
          lastY = touch.clientY;
          break;
        }
      }
    };
    this.domElement.addEventListener('touchstart', this._onLookTouchStart, { passive: true });

    this._onLookTouchMove = (e) => {
      if (this.lookLocked || this.lookTouchId === null) return;
      for (const touch of e.changedTouches) {
        if (touch.identifier !== this.lookTouchId) continue;
        const deltaX = touch.clientX - lastX;
        const deltaY = touch.clientY - lastY;
        lastX = touch.clientX;
        lastY = touch.clientY;

        // 从相机当前朝向出发累加，避免第一次拖动时视角跳变
        _euler.setFromQuaternion(this.camera.quaternion);
        _euler.y -= deltaX * 0.005;
        _euler.x -= deltaY * 0.005;
        _euler.x = Math.max(-Math.PI / 2 + 0.01, Math.min(Math.PI / 2 - 0.01, _euler.x));
        this.camera.quaternion.setFromEuler(_euler);
      }
    };
    this.domElement.addEventListener('touchmove', this._onLookTouchMove, { passive: true });

    this._onLookTouchEnd = (e) => {
      for (const touch of e.changedTouches) {
        if (touch.identifier === this.lookTouchId) {
          this.lookTouchId = null;
        }
      }
    };
    this.domElement.addEventListener('touchend', this._onLookTouchEnd);
    this.domElement.addEventListener('touchcancel', this._onLookTouchEnd);
  }

  /**
   * 键盘按下
   */
  onKeyDown(event) {
    if (!this.controls.isLocked && !this.freeMove) return;
    const code = event.code;
    if (code === 'Space') {
      event.preventDefault();
      if (!event.repeat) this.jump();
      return;
    }
    // 记录方向键按下时间
    if (!this.pressedKeys.has(code) && this.isMovementKey(code)) {
      this.keyPressTimes.set(code, performance.now());
    }
    this.pressedKeys.add(code);
    this.updateKeyState();
  }

  /**
   * 键盘抬起
   */
  onKeyUp(event) {
    const code = event.code;
    this.pressedKeys.delete(code);
    this.keyPressTimes.delete(code);
    this.updateKeyState();
  }

  isMovementKey(code) {
    return code === 'KeyW' || code === 'KeyS' || code === 'KeyA' || code === 'KeyD' ||
           code === 'ArrowUp' || code === 'ArrowDown' || code === 'ArrowLeft' || code === 'ArrowRight';
  }

  updateKeyState() {
    const keys = this.pressedKeys;
    this.moveForward = keys.has('KeyW') || keys.has('ArrowUp');
    this.moveBackward = keys.has('KeyS') || keys.has('ArrowDown');
    this.moveLeft = keys.has('KeyA') || keys.has('ArrowLeft');
    this.moveRight = keys.has('KeyD') || keys.has('ArrowRight');
    // Shift 键仍然可以手动触发冲刺
    this.canSprint = keys.has('ShiftLeft') || keys.has('ShiftRight');
  }

  stop() {
    this.pressedKeys.clear();
    this.keyPressTimes.clear();
    this.updateKeyState();
    this.velocity.set(0, 0, 0);
    this.lookTouchId = null;
    if (this.joystick) this.joystick.reset();
  }

  /**
   * 每帧更新：计算目标速度 → 平滑插值 → 水平移动 → 碰撞修正
   */
  update() {
    const time = performance.now();
    // 限制最大步长，防止切后台回来时一帧"瞬移"穿墙
    const delta = Math.min((time - this.prevTime) / 1000, 0.1);
    this.prevTime = time;

    // 目标速度（前进 / 右移）
    let targetForward = 0;
    let targetRight = 0;

    // 桌面端：WASD
    if (!this.isMobile && (this.controls.isLocked || this.freeMove)) {
      // 地图打开、鼠标未锁定时用 Q/E 转向（锁定时用鼠标）
      if (this.freeMove && !this.controls.isLocked) {
        const turn = Number(this.pressedKeys.has('KeyQ')) - Number(this.pressedKeys.has('KeyE'));
        if (turn) this.camera.rotateOnWorldAxis(this._turnAxis, turn * 1.6 * delta);
      }
      let f = Number(this.moveForward) - Number(this.moveBackward);
      let r = Number(this.moveRight) - Number(this.moveLeft);
      const len = Math.hypot(f, r);
      if (len > 0) {
        f /= len;
        r /= len;
      }
      // 检查是否有方向键持续按下超过 2 秒，自动启用冲刺
      let autoSprint = false;
      const now = time;
      for (const [code, pressTime] of this.keyPressTimes) {
        if (now - pressTime >= 2000) { // 2 秒
          autoSprint = true;
          break;
        }
      }
      const sprint = this.canSprint || autoSprint;
      const speed = sprint ? PLAYER.SPRINT_SPEED : PLAYER.MOVE_SPEED;
      targetForward = f * speed;
      targetRight = r * speed;
    }

    // 移动端：摇杆（向上推 = 前进，屏幕坐标 y 向下为正，所以取反）
    // 持续朝同一方向推满 2 秒以上 → 奔跑；换方向、松手或推得太轻都会回到走路
    let mobileRunning = false;
    if (this.isMobile && this.joystick && this.joystick.isActive()) {
      const d = this.joystick.getDelta();
      const mag = Math.hypot(d.x, d.y);
      if (mag > 0.5) {
        const angle = Math.atan2(d.x, -d.y);
        let diff = 0;
        if (this.runDirAngle !== null) {
          diff = Math.abs(angle - this.runDirAngle);
          if (diff > Math.PI) diff = 2 * Math.PI - diff;
        }
        if (this.runDirAngle === null || diff > (PLAYER.JOYSTICK_RUN_ANGLE ?? 0.6)) {
          this.runDirAngle = angle;
          this.runStartTime = time;
        }
        mobileRunning = time - this.runStartTime >= (PLAYER.JOYSTICK_RUN_DELAY ?? 2000);
      } else {
        this.runDirAngle = null;
      }
      if (mobileRunning) {
        // 奔跑时按满速，方向取当前推的方向
        targetForward = (-d.y / mag) * PLAYER.JOYSTICK_RUN_SPEED;
        targetRight = (d.x / mag) * PLAYER.JOYSTICK_RUN_SPEED;
      } else {
        targetForward = -d.y * PLAYER.JOYSTICK_SPEED;
        targetRight = d.x * PLAYER.JOYSTICK_SPEED;
      }
    } else {
      this.runDirAngle = null;
    }
    if (this.joystick && this.mobileRunning !== mobileRunning) this.joystick.setRunning(mobileRunning);
    this.mobileRunning = mobileRunning;

    // 速度平滑（指数插值，起步/停步更自然）
    const smoothing = 1 - Math.exp(-10 * delta);
    this.velocity.z += (targetForward - this.velocity.z) * smoothing;
    this.velocity.x += (targetRight - this.velocity.x) * smoothing;

    // 先去掉上一帧的镜头起伏偏移，碰撞只用无偏移的位置，避免累积漂移
    this.camera.position.sub(this.bobOffset);
    this.bobOffset.set(0, 0, 0);

    // 起跳：只有站在地面上才能跳（空中不能二段跳）
    this._landed = false;
    if (this.jumpQueued) {
      this.jumpQueued = false;
      const onGround = !this.airborne && this.feetY >= (this.groundY ?? 0) - 0.08;
      if (onGround) {
        this.airborne = true;
        this.verticalVelocity = PLAYER.JUMP_VELOCITY ?? 6.7;
        this.groundY = this.feetY;
      }
    }
    const air = this.airborne;

    let speed = 0;
    // 空中：碰撞按真实脚面（可越过矮栏杆）；地面：按逻辑地面（上楼梯不滞后）
    const baseFeet = air ? this.feetY : Math.max(this.feetY, this.groundY ?? 0);
    const eyeY = baseFeet + PLAYER.HEIGHT;
    this._trackedGround = null;
    // 速度很小时直接归零，避免无意义的碰撞计算
    if (Math.abs(this.velocity.z) < 0.01 && Math.abs(this.velocity.x) < 0.01) {
      this.velocity.set(0, 0, 0);
    } else {
      const currentPosition = this.camera.position.clone();
      currentPosition.y = eyeY;

      // 只在水平面移动
      this.controls.moveForward(this.velocity.z * delta);
      this.controls.moveRight(this.velocity.x * delta);

      // 碰撞检测（带沿墙滑动），用当前脚面高度对应的视点高度
      const newPosition = this.camera.position.clone();
      newPosition.y = eyeY;
      // 逐小步贴合地面（传入脚面），低帧率/快走一帧跨度大时也能正常上下台阶
      const validPosition = this.collisionManager.getValidPosition(
        currentPosition,
        newPosition,
        0.5,
        air ? (this.groundY ?? 0) : baseFeet,
        PLAYER.STEP_UP ?? 0.6,
        (air || this.onSupport) ? this.feetY : null
      );
      this._trackedGround = this.collisionManager.lastGroundY ?? null;

      this.camera.position.copy(validPosition);

      // 碰撞修正后的实际水平速度
      if (delta > 0) {
        speed = Math.hypot(validPosition.x - currentPosition.x, validPosition.z - currentPosition.z) / delta;
      }
    }

    this.updateGround(delta);
    this.camera.position.y = this.feetY + PLAYER.HEIGHT;

    const sprint = this.isMobile
      ? mobileRunning && speed > PLAYER.MOVE_SPEED * 0.5
      : this.canSprint && speed > PLAYER.MOVE_SPEED * 0.5;
    // 空中不计脚步、不晃镜头；落地那一帧补一声脚步
    const footstep = this.updateHeadBob(delta, this.airborne ? 0 : speed) || this._landed;
    this.motion.speed = speed;
    this.motion.sprint = sprint;
    this.motion.footstep = footstep;
  }

  /**
   * 脚面高度跟随地面：上台阶/上坡平滑抬升；地面降低时按重力下落（走下台阶、从台基边缘下来）
   */
  updateGround(delta) {
    // 以"逻辑地面"（上一帧所站的面）为基准查询，避免上长楼梯时镜头平滑滞后超过可迈高度而误判掉落
    const base = Math.max(this.feetY, this.groundY ?? 0);
    // 本帧移动过：用移动过程中逐小步追踪得到的地面；否则在原地查询
    const walkY = this._trackedGround ?? this.collisionManager.getGroundHeight(
      this.camera.position.x, this.camera.position.z, this.airborne ? this.feetY : base, PLAYER.STEP_UP ?? 0.6
    );
    // 栏杆 / 家具 / 矮墙顶面也能站（只认脚下方的，不会"走上"高物体）
    const sup = this.collisionManager.supportHeight?.(
      this.camera.position.x, this.camera.position.z, this.feetY + 0.05
    ) ?? -Infinity;
    const groundY = Math.max(walkY, sup);
    this.onSupport = sup > walkY + 0.01;
    this.groundY = groundY;
    // 地面骤降（从台基边缘、栏杆上走下去）转入空中状态：按真实身体高度判碰撞，不会卡进栏杆
    if (!this.airborne && groundY < this.feetY - (PLAYER.STEP_UP ?? 0.6)) {
      this.airborne = true;
      this.verticalVelocity = 0;
    }
    if (this.airborne) {
      // 跳到略高于脚面的台面上：脚面抬到台面，不陷进去
      if (this.feetY < groundY) {
        this.feetY = groundY;
        if (this.verticalVelocity <= 0) {
          this.verticalVelocity = 0;
          this.airborne = false;
          this._landed = true;
          return;
        }
      }
      // 跳跃中：竖直速度受重力，下落到脚下地面即落地
      const g = PLAYER.GRAVITY ?? 14;
      this.verticalVelocity = Math.max(this.verticalVelocity - g * delta, -(PLAYER.MAX_FALL_SPEED ?? 30));
      this.feetY += this.verticalVelocity * delta;
      if (this.verticalVelocity <= 0 && this.feetY <= groundY) {
        this.feetY = groundY;
        this.verticalVelocity = 0;
        this.airborne = false;
        this._landed = true;
      }
      return;
    }
    if (groundY >= this.feetY - 0.02) {
      // 上行或贴地：快速平滑跟随，避免台阶处抖动
      this.verticalVelocity = 0;
      const follow = 1 - Math.exp(-14 * delta);
      this.feetY += (groundY - this.feetY) * follow;
      if (Math.abs(groundY - this.feetY) < 0.005) this.feetY = groundY;
    } else {
      // 下落：重力加速，落到地面即停
      this.verticalVelocity = Math.max(this.verticalVelocity - 9.8 * delta, -12);
      this.feetY += this.verticalVelocity * delta;
      if (this.feetY <= groundY) {
        this.feetY = groundY;
        this.verticalVelocity = 0;
      }
    }
  }

  /**
   * 推进步频相位并把起伏偏移叠加到相机上；返回本帧是否落脚
   */
  updateHeadBob(delta, speed) {
    const walking = speed >= HEAD_BOB.MIN_STEP_SPEED;

    // 步频：0~走路速度按平方根缩放，走路~冲刺速度之间线性过渡，超出部分再按平方根缩放
    let stepRate = 0;
    if (walking) {
      if (speed <= PLAYER.MOVE_SPEED) {
        stepRate = HEAD_BOB.WALK_STEP_RATE * Math.sqrt(speed / PLAYER.MOVE_SPEED);
      } else if (speed <= PLAYER.SPRINT_SPEED) {
        const t = (speed - PLAYER.MOVE_SPEED) / (PLAYER.SPRINT_SPEED - PLAYER.MOVE_SPEED);
        stepRate = HEAD_BOB.WALK_STEP_RATE + (HEAD_BOB.SPRINT_STEP_RATE - HEAD_BOB.WALK_STEP_RATE) * t;
      } else {
        stepRate = HEAD_BOB.SPRINT_STEP_RATE * Math.sqrt(speed / PLAYER.SPRINT_SPEED);
      }
    }

    const prevPhase = this.bobPhase;
    this.bobPhase += stepRate * delta;
    const footstep = walking && Math.floor(this.bobPhase) > Math.floor(prevPhase);
    // 相位只关心小数部分与左右脚奇偶，定期回绕避免浮点精度损失
    if (this.bobPhase > 1000) this.bobPhase -= 1000;

    if (!this.headBobEnabled) {
      this.bobAmplitude = 0;
      return footstep;
    }

    // 目标振幅：慢走按速度比例减小，走路→冲刺之间插值；停下时平滑回落到 0
    let targetAmplitude = 0;
    if (walking) {
      const sprintMix = Math.min(Math.max((speed - PLAYER.MOVE_SPEED) / (PLAYER.SPRINT_SPEED - PLAYER.MOVE_SPEED), 0), 1);
      const base = HEAD_BOB.WALK_AMPLITUDE + (HEAD_BOB.SPRINT_AMPLITUDE - HEAD_BOB.WALK_AMPLITUDE) * sprintMix;
      targetAmplitude = base * Math.min(1, speed / PLAYER.MOVE_SPEED);
    }
    this.bobAmplitude += (targetAmplitude - this.bobAmplitude) * (1 - Math.exp(-HEAD_BOB.SMOOTHING * delta));
    if (targetAmplitude === 0 && this.bobAmplitude < 1e-4) this.bobAmplitude = 0;
    if (this.bobAmplitude === 0) return footstep;

    // 上下：每步一个周期，落脚（相位为整数）时处于最低点；左右：频率减半，沿相机水平右向量
    const k = this.bobAmplitude / HEAD_BOB.WALK_AMPLITUDE;
    const vertical = -this.bobAmplitude * Math.cos(2 * Math.PI * this.bobPhase);
    const sway = HEAD_BOB.SWAY_AMPLITUDE * Math.min(k, 1) * Math.cos(Math.PI * this.bobPhase);
    _right.set(1, 0, 0).applyQuaternion(this.camera.quaternion);
    _right.y = 0;
    if (_right.lengthSq() > 1e-8) _right.normalize();
    this.bobOffset.set(_right.x * sway, vertical, _right.z * sway);
    this.camera.position.add(this.bobOffset);
    return footstep;
  }

  /**
   * 开关镜头起伏（关闭时立即回到无偏移位置）
   */
  setHeadBob(enabled) {
    this.headBobEnabled = !!enabled;
    if (!this.headBobEnabled) {
      this.camera.position.sub(this.bobOffset);
      this.bobOffset.set(0, 0, 0);
      this.bobAmplitude = 0;
    }
  }

  /**
   * 获取控制器对象（即相机）
   */
  getObject() {
    return this.camera;
  }

  /**
   * 获取当前位置
   */
  getPosition() {
    return this.camera.position;
  }

  /**
   * 设置位置
   */
  setPosition(x, y, z) {
    this.camera.position.set(x, y, z);
    this.bobOffset.set(0, 0, 0);
    this.bobAmplitude = 0;
    // 传入的 y 视为视点高度；脚面取其下 PLAYER.HEIGHT，再贴合该处地面
    this.feetY = Math.max(0, y - PLAYER.HEIGHT);
    this.verticalVelocity = 0;
    this.airborne = false;
    this.onSupport = false;
    this.jumpQueued = false;
    if (this.collisionManager?.getGroundHeight) {
      this.feetY = this.collisionManager.getGroundHeight(x, z, this.feetY, PLAYER.STEP_UP ?? 0.6);
      this.camera.position.y = this.feetY + PLAYER.HEIGHT;
    }
    this.groundY = this.feetY;
  }

  /**
   * 当前脚面高度（米）
   */
  getFeetY() {
    return this.feetY;
  }

  /**
   * 让视线朝向某个点（只取水平方向，保持平视）
   */
  lookAt(x, z) {
    this.camera.lookAt(x, this.camera.position.y, z);
  }

  teleportTo(x, z, lookAtX, lookAtZ) {
    const ground = this.collisionManager.getGroundHeight(x, z, Infinity);
    this.stop();
    this.setPosition(x, ground + PLAYER.HEIGHT, z);
    this.lookAt(lookAtX, lookAtZ);
  }

  /**
   * 锁定指针
   */
  lock() {
    if (!this.isMobile) {
      this.controls.lock();
    }
  }

  /**
   * 解锁指针
   */
  unlock() {
    this.stop();
    if (!this.isMobile) {
      this.controls.unlock();
    }
  }

  /** 地图打开时：允许在未锁定指针的情况下继续用键盘移动 */
  setFreeMove(on) {
    this.freeMove = !!on;
    if (!on) this.stop();
  }

  /**
   * 检查是否锁定
   */
  isLocked() {
    return this.isMobile || this.controls.isLocked;
  }

  /**
   * 销毁
   */
  dispose() {
    this.stop();
    window.removeEventListener('blur', this._onStop);
    document.removeEventListener('keydown', this._onKeyDown);
    document.removeEventListener('keyup', this._onKeyUp);
    this.controls.removeEventListener('unlock', this._onUnlockStop);
    if (this._onClick) {
      this.domElement.removeEventListener('click', this._onClick);
    }
    if (this.lookLockButton) {
      this.domElement.removeEventListener('touchstart', this._onLookTouchStart);
      this.domElement.removeEventListener('touchmove', this._onLookTouchMove);
      this.domElement.removeEventListener('touchend', this._onLookTouchEnd);
      this.domElement.removeEventListener('touchcancel', this._onLookTouchEnd);
      this.lookLockButton.removeEventListener('click', this._onLookLockClick);
      this.lookLockButton.remove();
      this.lookLockButton = null;
    }
    if (this.jumpButton) {
      this.jumpButton.removeEventListener('touchstart', this._onJumpTouch);
      this.jumpButton.remove();
      this.jumpButton = null;
    }
    if (this.joystick) {
      this.joystick.dispose();
    }
    if (this.controls.isLocked) this.controls.unlock();
    this.controls.dispose();
  }
}

/**
 * 虚拟方向盘（移动端）
 * 常驻显示在左下角的半透明圆盘：按住圆盘拖动即可前后左右移动，松手归零。
 * 只认领落在圆盘附近的那根手指，其余手指留给视角拖动。
 */

const SIZE = 120;          // 底座直径（px）
const KNOB = 54;           // 摇杆头直径（px）
const HIT_PADDING = 45;    // 圆盘外扩的可触发范围（px），手指没按准也能用

export class VirtualJoystick {
  constructor(container) {
    this.container = container;
    this.active = false;
    this.baseX = 0;
    this.baseY = 0;
    this.stickX = 0;
    this.stickY = 0;
    this.deltaX = 0;
    this.deltaY = 0;
    this.touchId = null;

    this.maxRadius = (SIZE - KNOB) / 2 + 10;

    this.createElements();
    this.bindEvents();
  }

  /**
   * 创建 DOM 元素（常驻显示）
   */
  createElements() {
    this.base = document.createElement('div');
    this.base.className = 'joystick-base';
    this.base.style.cssText = `
      position: fixed;
      left: calc(28px + env(safe-area-inset-left, 0px));
      bottom: calc(36px + env(safe-area-inset-bottom, 0px));
      width: ${SIZE}px;
      height: ${SIZE}px;
      background: radial-gradient(circle, rgba(255,255,255,0.10) 0%, rgba(255,255,255,0.22) 100%);
      border: 2px solid rgba(255, 255, 255, 0.45);
      border-radius: 50%;
      box-shadow: 0 2px 12px rgba(0, 0, 0, 0.25);
      z-index: 1000;
      pointer-events: none;
      transition: opacity 0.2s ease, background 0.2s ease;
      opacity: 0.75;
    `;

    // 上下左右方向箭头
    const arrows = [
      { ch: '▲', css: 'top: 6px; left: 50%; transform: translateX(-50%);' },
      { ch: '▼', css: 'bottom: 6px; left: 50%; transform: translateX(-50%);' },
      { ch: '◀', css: 'left: 8px; top: 50%; transform: translateY(-50%);' },
      { ch: '▶', css: 'right: 8px; top: 50%; transform: translateY(-50%);' },
    ];
    for (const a of arrows) {
      const el = document.createElement('span');
      el.textContent = a.ch;
      el.style.cssText = `position: absolute; ${a.css} font-size: 12px; line-height: 1; color: rgba(255,255,255,0.75); pointer-events: none;`;
      this.base.appendChild(el);
    }

    this.stick = document.createElement('div');
    this.stick.className = 'joystick-stick';
    this.stick.style.cssText = `
      position: absolute;
      top: 50%;
      left: 50%;
      width: ${KNOB}px;
      height: ${KNOB}px;
      background: rgba(255, 255, 255, 0.55);
      border: 2px solid rgba(255, 255, 255, 0.85);
      border-radius: 50%;
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
      transform: translate(-50%, -50%);
      pointer-events: none;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #7a4a00;
      font-size: 16px;
      font-weight: bold;
    `;

    this.base.appendChild(this.stick);
    this.container.appendChild(this.base);
  }

  bindEvents() {
    this._onTouchStart = this.onTouchStart.bind(this);
    this._onTouchMove = this.onTouchMove.bind(this);
    this._onTouchEnd = this.onTouchEnd.bind(this);
    this.container.addEventListener('touchstart', this._onTouchStart, { passive: false });
    this.container.addEventListener('touchmove', this._onTouchMove, { passive: false });
    this.container.addEventListener('touchend', this._onTouchEnd, { passive: false });
    this.container.addEventListener('touchcancel', this._onTouchEnd, { passive: false });
  }

  /**
   * 圆盘中心（屏幕坐标），每次按下时实时读取，兼容横竖屏切换
   */
  getCenter() {
    const r = this.base.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2, radius: r.width / 2 };
  }

  /**
   * 某个触点是否落在方向盘可触发范围内
   */
  hitTest(x, y) {
    const c = this.getCenter();
    return Math.hypot(x - c.x, y - c.y) <= c.radius + HIT_PADDING;
  }

  onTouchStart(e) {
    if (this.active) return;
    const touch = Array.from(e.changedTouches).find(t =>
      !t.target?.closest?.('button, a, input, select, textarea, [role="button"]') &&
      this.hitTest(t.clientX, t.clientY)
    );
    if (!touch) return;
    e.preventDefault();
    this.touchId = touch.identifier;

    const c = this.getCenter();
    this.baseX = c.x;
    this.baseY = c.y;
    this.active = true;
    this.base.style.opacity = '1';
    this.base.style.background = 'radial-gradient(circle, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0.32) 100%)';
    this.updateStick(touch.clientX, touch.clientY);
  }

  onTouchMove(e) {
    if (!this.active) return;
    const touch = Array.from(e.changedTouches).find(t => t.identifier === this.touchId);
    if (!touch) return;
    e.preventDefault();
    this.updateStick(touch.clientX, touch.clientY);
  }

  updateStick(x, y) {
    const dx = x - this.baseX;
    const dy = y - this.baseY;
    const distance = Math.hypot(dx, dy);
    if (distance > this.maxRadius) {
      this.stickX = (dx / distance) * this.maxRadius;
      this.stickY = (dy / distance) * this.maxRadius;
    } else {
      this.stickX = dx;
      this.stickY = dy;
    }
    this.stick.style.transform = `translate(calc(-50% + ${this.stickX}px), calc(-50% + ${this.stickY}px))`;

    // 归一化偏移（-1 ~ 1），中心留一点死区，防止手指微抖导致漂移
    let nx = this.stickX / this.maxRadius;
    let ny = this.stickY / this.maxRadius;
    if (Math.hypot(nx, ny) < 0.12) { nx = 0; ny = 0; }
    this.deltaX = nx;
    this.deltaY = ny;
  }

  onTouchEnd(e) {
    const touch = Array.from(e.changedTouches).find(t => t.identifier === this.touchId);
    if (!touch) return;
    this.reset();
  }

  reset() {
    this.active = false;
    this.touchId = null;
    this.stickX = 0;
    this.stickY = 0;
    this.deltaX = 0;
    this.deltaY = 0;
    this.stick.style.transform = 'translate(-50%, -50%)';
    if (this.base) {
      this.base.style.opacity = '0.75';
      this.base.style.background = 'radial-gradient(circle, rgba(255,255,255,0.10) 0%, rgba(255,255,255,0.22) 100%)';
    }
  }

  /**
   * 奔跑状态：圆盘边框变金色并显示"跑"字提示
   */
  setRunning(running) {
    this.running = !!running;
    if (!this.base) return;
    this.base.style.borderColor = running ? 'rgba(255, 200, 60, 0.95)' : 'rgba(255, 255, 255, 0.45)';
    this.base.style.boxShadow = running
      ? '0 0 16px rgba(255, 200, 60, 0.7)'
      : '0 2px 12px rgba(0, 0, 0, 0.25)';
    this.stick.textContent = running ? '跑' : '';
  }

  getDelta() {
    return { x: this.deltaX, y: this.deltaY };
  }

  isActive() {
    return this.active;
  }

  dispose() {
    this.container.removeEventListener('touchstart', this._onTouchStart);
    this.container.removeEventListener('touchmove', this._onTouchMove);
    this.container.removeEventListener('touchend', this._onTouchEnd);
    this.container.removeEventListener('touchcancel', this._onTouchEnd);
    this.reset();
    if (this.base && this.base.parentNode) {
      this.base.parentNode.removeChild(this.base);
    }
  }
}

import * as THREE from 'three';
import { LAYOUT, PLAYER } from '../config/constants.js';
import { PALACE_LAYOUT } from '../scene/Layout.js';
import { isOnBridge } from '../scene/palace/river.js';

/** 玩家碰撞盒底部离脚面的抬升量：低于此高度的台阶/门槛直接跨过，不当成墙。 */
const STEP_CLEARANCE = 0.35;

/** 实体碰撞代理与河道通行检查；不把整个建筑的空区当成实心。 */
export class CollisionManager {
  constructor() {
    this.colliders = [];
    /**
     * 可行走面（台基顶面、楼梯斜坡、桥面）。
     * - { type: 'box', box: Box3 }：顶面高度 = box.max.y，XZ 范围取 box。
     * - { type: 'ramp', minX, maxX, minZ, maxZ, axis: 'x'|'z', a0, a1, y0, y1 }：
     *   沿 axis 从坐标 a0（高度 y0）到 a1（高度 y1）线性过渡。
     *   Optional crossMin0/crossMax0/crossMin1/crossMax1 bound a tapered
     *   cross-axis interval at a0/a1; absent fields preserve rectangles.
     */
    this.walkables = [];
    this.playerBox = new THREE.Box3();
    this.playerSize = new THREE.Vector3();
    this.playerCenter = new THREE.Vector3();
    this.rivers = PALACE_LAYOUT.filter(item => item.type === 'river');
  }

  addCollider(object, tag) {
    const box = object.isBox3 ? object.clone() : new THREE.Box3().setFromObject(object);
    if (!box.isEmpty()) this.colliders.push({ mesh: object, box, tag });
  }

  addColliders(objects, tag) {
    objects.forEach(object => this.addCollider(object, tag));
  }

  addWalkable(walkable, tag) {
    if (!walkable) return;
    if (walkable.type === 'box') {
      const box = walkable.box.isBox3 ? walkable.box.clone() : new THREE.Box3().setFromObject(walkable.box);
      // rescue: false —— 不做"钻进台基托回台面"（城台顶面下方有门洞，从门洞穿过时不能被托上城台）
      if (!box.isEmpty()) this.walkables.push({ type: 'box', box, rescue: walkable.rescue !== false, tag });
      return;
    }
    if (walkable.type === 'ramp') {
      const r = walkable;
      const taper = ['crossMin0', 'crossMax0', 'crossMin1', 'crossMax1'];
      const hasTaper = taper.some(key => r[key] !== undefined);
      if (hasTaper && (!taper.every(key => Number.isFinite(r[key])) || r.crossMin0 > r.crossMax0 || r.crossMin1 > r.crossMax1)) {
        throw new Error('Invalid tapered ramp: four finite, ordered cross-axis bounds are required');
      }
      this.walkables.push({
        type: 'ramp',
        minX: Math.min(r.minX, r.maxX), maxX: Math.max(r.minX, r.maxX),
        minZ: Math.min(r.minZ, r.maxZ), maxZ: Math.max(r.minZ, r.maxZ),
        axis: r.axis === 'x' ? 'x' : 'z', a0: r.a0, a1: r.a1, y0: r.y0, y1: r.y1,
        ...(hasTaper
          ? { crossMin0: r.crossMin0, crossMax0: r.crossMax0, crossMin1: r.crossMin1, crossMax1: r.crossMax1 } : {}),
        tag,
      });
    }
  }

  addWalkables(list, tag) {
    (list ?? []).forEach(item => this.addWalkable(item, tag));
  }

  /**
   * 删除带指定 tag 的所有 colliders 和 walkables（用于区域卸载）
   */
  removeByTag(tag) {
    if (!tag) return;
    const beforeC = this.colliders.length;
    const beforeW = this.walkables.length;
    this.colliders = this.colliders.filter(c => c.tag !== tag);
    this.walkables = this.walkables.filter(w => w.tag !== tag);
    const removedC = beforeC - this.colliders.length;
    const removedW = beforeW - this.walkables.length;
    if (removedC > 0 || removedW > 0) {
      this._grid = null; // 重建网格
    }
  }

  /**
   * 脚点 (x, z) 处的地面高度：取所有覆盖该点、且顶面不高于 feetY + stepUp 的可行走面中最高者；
   * 没有任何可行走面时为地面 0。
   */
  getGroundHeight(x, z, feetY = 0, stepUp = 0.6) {
    let ground = 0;
    let rescue = 0;
    const limit = feetY + stepUp;
    const m = 0.6; // 台基实体内缩量：玩家半径 + 余量
    for (const w of this.walkables) {
      let top;
      if (w.type === 'box') {
        const b = w.box;
        if (x < b.min.x || x > b.max.x || z < b.min.z || z > b.max.z) continue;
        top = b.max.y;
        // 台基是实心的：脚点已深入台基投影内部却低于台面，说明从台阶口"钻"进了台基，直接托回台面，
        // 杜绝"走到楼梯顶掉到宫殿底下"。
        if (w.rescue && top > limit && x > b.min.x + m && x < b.max.x - m && z > b.min.z + m && z < b.max.z - m) {
          rescue = Math.max(rescue, top);
        }
      } else {
        if (x < w.minX || x > w.maxX || z < w.minZ || z > w.maxZ) continue;
        const a = w.axis === 'x' ? x : z;
        const t = w.a1 === w.a0 ? 1 : Math.min(1, Math.max(0, (a - w.a0) / (w.a1 - w.a0)));
        // Optional trapezoidal boundary: cross-axis edges interpolate at the
        // same t as the height. Legacy rectangular ramps retain their exact path.
        if (w.crossMin0 !== undefined) {
          const cross = w.axis === 'x' ? z : x;
          const low = w.crossMin0 + (w.crossMin1 - w.crossMin0) * t;
          const high = w.crossMax0 + (w.crossMax1 - w.crossMax0) * t;
          if (cross < low - 1e-9 || cross > high + 1e-9) continue;
        }
        top = w.y0 + (w.y1 - w.y0) * t;
      }
      if (top > limit || top <= ground) continue;
      ground = top;
    }
    return Math.max(ground, rescue);
  }

  checkCollision(position, radius = 0.5) {
    if (!this.checkBoundary(position, radius) || !this.checkRiverCrossing(position, radius)) return true;
    // 视点是头部（脚面 + PLAYER.HEIGHT）；碰撞体从脚面上方 STEP_CLEARANCE 到头顶，矮台阶可直接跨过。
    const feetY = position.y - PLAYER.HEIGHT;
    const bottom = feetY + STEP_CLEARANCE;
    const top = position.y - 0.05;
    this.playerSize.set(radius * 2, top - bottom, radius * 2);
    this.playerCenter.set(position.x, (top + bottom) / 2, position.z);
    this.playerBox.setFromCenterAndSize(this.playerCenter, this.playerSize);
    return this.queryBox(this.playerBox).some(collider => this.playerBox.intersectsBox(collider.box));
  }

  /**
   * 空间网格（XZ 平面，CELL 米一格）：碰撞体多了以后只检查附近格子里的，射线/子弹检测也可复用。
   * 碰撞体增删后自动失效重建。
   */
  _buildGrid() {
    const CELL = 8;
    const grid = new Map();
    for (const c of this.colliders) {
      const b = c.box;
      const i0 = Math.floor(b.min.x / CELL), i1 = Math.floor(b.max.x / CELL);
      const k0 = Math.floor(b.min.z / CELL), k1 = Math.floor(b.max.z / CELL);
      for (let i = i0; i <= i1; i++) for (let k = k0; k <= k1; k++) {
        const key = i * 100003 + k;
        let list = grid.get(key);
        if (!list) grid.set(key, list = []);
        list.push(c);
      }
    }
    this._grid = { CELL, grid, count: this.colliders.length };
  }

  /** 返回与 box 的 XZ 投影可能相交的碰撞体（去重） */
  queryBox(box) {
    if (!this._grid || this._grid.count !== this.colliders.length) this._buildGrid();
    const { CELL, grid } = this._grid;
    const i0 = Math.floor(box.min.x / CELL), i1 = Math.floor(box.max.x / CELL);
    const k0 = Math.floor(box.min.z / CELL), k1 = Math.floor(box.max.z / CELL);
    if (i0 === i1 && k0 === k1) return grid.get(i0 * 100003 + k0) ?? [];
    const out = new Set();
    for (let i = i0; i <= i1; i++) for (let k = k0; k <= k1; k++) grid.get(i * 100003 + k)?.forEach(c => out.add(c));
    return [...out];
  }

  /**
   * 脚下碰撞体能提供的支撑高度：脚印（半径 r）范围内、顶面不高于 maxTop 的碰撞体顶面最大值。
   * 跳到栏杆、家具、矮墙上时用它当"地面"，避免从上方落进碰撞体里卡死。没有则返回 -Infinity。
   */
  supportHeight(x, z, maxTop, r = 0.3) {
    this._footBox ??= new THREE.Box3();
    this._footBox.min.set(x - r, -1e3, z - r);
    this._footBox.max.set(x + r, 1e3, z + r);
    let best = -Infinity;
    for (const c of this.queryBox(this._footBox)) {
      const b = c.box;
      if (b.max.y > maxTop || b.max.y <= best) continue;
      if (x + r < b.min.x || x - r > b.max.x || z + r < b.min.z || z - r > b.max.z) continue;
      best = b.max.y;
    }
    return best;
  }

  checkBoundary(position, radius = 0.5) {
    const { minX, maxX, minZ, maxZ } = LAYOUT.BOUNDARY;
    return position.x - radius >= minX && position.x + radius <= maxX &&
      position.z - radius >= minZ && position.z + radius <= maxZ;
  }

  checkRiverCrossing(position, radius) {
    for (const river of this.rivers) {
      const { position: p, dimensions: d } = river;
      const insideX = position.x + radius > p.x - d.width / 2 && position.x - radius < p.x + d.width / 2;
      const insideZ = position.z + radius > p.z - d.depth / 2 && position.z - radius < p.z + d.depth / 2;
      if (!insideX || !insideZ) continue;
      // 桥位 / 桥宽唯一数据源：src/scene/palace/river.js（Layout 金水河条目 bridges）
      if (!isOnBridge(river, position.x, radius)) return false;
    }
    return true;
  }

  /**
   * 水平移动 + 碰撞修正（沿墙滑动）。
   * 传入 feetY 时，每个细分小步都重新贴合地面（台阶/坡道），并用该小步的地面高度做碰撞检测。
   * 这样低帧率或快走时一帧走 1m 以上，也不会因为"一帧抬升超过可迈高度"而判定上不去台阶、
   * 继续以地面高度从楼梯口钻进台基内部（表现为走到楼梯顶突然掉到台基下面）。
   * 结果的地面高度写入 this.lastGroundY。
   */
  getValidPosition(currentPosition, targetPosition, radius = 0.5, feetY = null, stepUp = PLAYER.STEP_UP ?? 0.6, airFeet = null) {
    // airFeet：空中（跳跃/下落）时的实际脚面高度。碰撞按身体真实高度判定（可越过矮栏杆），
    // 落脚面按真实脚面查询（跳到高于原地面的台面上也能落住）。
    const distance = Math.hypot(targetPosition.x - currentPosition.x, targetPosition.z - currentPosition.z);
    const steps = Math.max(1, Math.ceil(distance / Math.max(radius * 0.5, 0.05)));
    const dx = (targetPosition.x - currentPosition.x) / steps;
    const dz = (targetPosition.z - currentPosition.z) / steps;
    const valid = currentPosition.clone();
    const candidate = currentPosition.clone();
    const track = feetY !== null && feetY !== undefined;
    let ground = track ? feetY : 0;
    const air = track && airFeet !== null && airFeet !== undefined;
    const tryMove = (x, z) => {
      const g = track ? this.getGroundHeight(x, z, air ? Math.max(airFeet, ground) : ground, stepUp) : 0;
      const bodyFeet = air ? Math.max(g, airFeet) : g;
      candidate.set(x, track ? bodyFeet + PLAYER.HEIGHT : valid.y, z);
      if (this.checkCollision(candidate, radius)) return false;
      valid.copy(candidate);
      if (track) ground = g;
      return true;
    };
    for (let i = 0; i < steps; i++) {
      if (tryMove(valid.x + dx, valid.z + dz)) continue;
      tryMove(valid.x + dx, valid.z);
      tryMove(valid.x, valid.z + dz);
    }
    this.lastGroundY = ground;
    return valid;
  }

  updateCollider(object) {
    const collider = this.colliders.find(item => item.mesh === object);
    if (collider) {
      if (object.isBox3) collider.box.copy(object);
      else collider.box.setFromObject(object);
      this._grid = null;
    }
  }

  clear() {
    this.colliders.length = 0;
    this.walkables.length = 0;
    this._grid = null;
  }

  /** 两侧宫院的命名区域（世界坐标矩形），优先于中轴 z 分段判断 */
  setRegions(regions) {
    // 面积小的优先（院内的殿 > 整片街区）
    this.regions = [...(regions ?? [])].sort((a, b) =>
      (a.maxX - a.minX) * (a.maxZ - a.minZ) - (b.maxX - b.minX) * (b.maxZ - b.minZ));
  }

  getCurrentLocation(position) {
    const { x, z } = position;
    const hit = this.regions?.find(r => x >= r.minX && x <= r.maxX && z >= r.minZ && z <= r.maxZ);
    if (hit) return hit.name;
    // 兜底分段（真实米制）：外朝东西庑墙 ≈ ±106.5 / 110.7，内廷东西一长街墙 ±54.25，御花园墙 ±68
    if (Math.abs(x) > LAYOUT.PALACE_RECT.halfX) return x < 0 ? '东华门外' : '西华门外';
    if (Math.abs(x) > 106 && z > LAYOUT.WUMEN_Z + 4 && z < 204) return x < 0 ? '东路·文华殿一带' : '西路·武英殿一带';
    if (Math.abs(x) > 54 && z >= 204 && z < 422.7) return x < 0 ? '东六宫' : '西六宫';
    if (Math.abs(x) > 68 && z >= 422.7) return x < 0 ? '东路·宁寿宫一带' : '西路·建福宫一带';
    if (z < LAYOUT.WUMEN_Z - 30) return '午门外广场';
    if (z < LAYOUT.TAIHE_GATE_Z - 20) return '午门';
    if (z < LAYOUT.TAIHE_Z - 30) return '太和门广场';
    if (z < LAYOUT.TAIHE_Z + 20) return '太和殿';
    if (z < LAYOUT.ZHONGHE_Z + 15) return '中和殿';
    if (z < LAYOUT.BAOHE_Z + 20) return '保和殿';
    if (z < LAYOUT.QIANQING_GATE_Z - 20) return '内廷广场';
    if (z < LAYOUT.QIANQING_Z + 15) return '乾清宫';
    if (z < LAYOUT.JIAOTAI_Z + 10) return '交泰殿';
    if (z < LAYOUT.KUNNING_Z + 15) return '坤宁宫';
    if (z < LAYOUT.IMPERIAL_GARDEN_Z + 30) return '御花园';
    if (z < LAYOUT.SHENWU_Z + 20) return '神武门';
    return '神武门外';
  }
}

/** Explicit opt-in test driver for physical stair contacts. This never changes
 * production controller speeds, collision, rescue, or the original route driver.
 * New fast routes use sprint on straight runs and walk within2m of a corner/end.
 */
export const PHYSICAL_WAYPOINT_DRIVER = 'physical-crossing-v1';
export function createPhysicalWaypointDriver(points) {
  let index=1;
  const crossings=[];
  let brakingFrames=0;
  return {
    get index(){return index;},
    get complete(){return index>=points.length;},
    get diagnostics(){return {crossings:[...crossings],brakingFrames,endpointSettleSeconds:2};},
    command(position,sprint){
      let aim=index;
      while(aim+1<points.length) {
        const ax=points[aim][0]-points[aim-1][0],az=points[aim][1]-points[aim-1][1];
        const bx=points[aim+1][0]-points[aim][0],bz=points[aim+1][1]-points[aim][1];
        if((ax*bx+az*bz)/(Math.hypot(ax,az)*Math.hypot(bx,bz))<.999999)break;
        aim++;
      }
      const target=points[aim],canSprint=sprint&&Math.hypot(target[0]-position[0],target[1]-position[1])>2;
      if(sprint&&!canSprint)brakingFrames++;
      return {target,canSprint};
    },
    observe(before,after){
      let advanced=0;
      while(index<points.length) {
        const q=points[index],prev=points[index-1],lx=q[0]-prev[0],lz=q[1]-prev[1],len=Math.hypot(lx,lz),ux=lx/len,uz=lz/len;
        const a=(before[0]-q[0])*ux+(before[1]-q[1])*uz,b=(after[0]-q[0])*ux+(after[1]-q[1])*uz;
        const fraction=Math.max(0,Math.min(1,-a/(b-a))),hit=[before[0]+(after[0]-before[0])*fraction,before[1]+(after[1]-before[1])*fraction];
        const distance=Math.hypot(hit[0]-q[0],hit[1]-q[1]);
        if(!(a<=.01&&b>=-.01&&distance<.6))break;
        crossings.push({index,point:[...q],hit,lateralDistance:distance});
        index++;advanced++;
        // A frame can cross several collinear contacts, never a later turn.
        if(index<points.length) {
          const nx=points[index][0]-q[0],nz=points[index][1]-q[1];
          if((nx*ux+nz*uz)/Math.hypot(nx,nz)<.999999)break;
        }
      }
      return advanced;
    },
  };
}

const { browserExecutablePath } = require('./browser-path.cjs');
// stepwalk 浏览器执行器（stepwalk.cjs / stepwalk-auto.cjs 共用）。
// 用固定帧间隔逐帧调用真实 FirstPersonControls.update，复现低帧率/冲刺下的台阶问题；由本脚本代为推进 ZoneManager。
// 判定：每个途经点 0.8 m 内到达（连续 2 秒移动 < 0.3 m 视为卡住）且未"掉到台下"。
// 额外记录（自动路线用）：途经的分区序列、加载/卸载事件、"所在区未加载时的行走距离"（流式加载期间碰撞缺失）。
//
// S 档内景（InteriorLoader）：门禁按"全部 S 档内景已加载"的最坏情况测碰撞。
// 背景：本执行器会停掉主循环，之后不会再调 interiors.update，且 runRoutes 是同步 evaluate，GLB 异步加载永远完不成，
// 不预加载的话 S 档碰撞体/可行走面全不存在，门禁对内景是"盲"的。所以 openPage() 就绪后先预加载全部 S 档：
//   1) 先把 interiors.update 换成空函数（否则主循环残留的 update 会因距离 > 40 m 把正在加载的殿卸掉）
//   2) 逐个 await interiors.load(id)
//   3) 校验每座 state === 'loaded' 且 collisionManager 里有 tag = interior:<id> 的碰撞体，否则抛错（防止再次"变盲"）
// 接线丢失（window.__forbiddenCityApp.interiors 不存在）同样抛错。STEPWALK_NO_INTERIORS=1 可关闭预加载（仅调试用）。
const { chromium } = require('playwright');

async function preloadInteriors(page) {
  const res = await page.evaluate(async () => {
    const a = window.__forbiddenCityApp;
    const il = a?.interiors;
    if (!il) throw new Error('window.__forbiddenCityApp.interiors 不存在（InteriorLoader 接线丢失），门禁无法覆盖内景');
    il.update = () => {}; // 冻结距离触发，由本函数全权管理加载
    const ids = il.ids();
    if (!ids.length) throw new Error('InteriorLoader 未注册任何内景');
    for (const id of ids) await il.load(id);
    const cm = a.collisionManager;
    return ids.map(id => ({
      id,
      state: il.getState(id),
      col: cm.colliders.filter(c => c.tag === `interior:${id}`).length,
      walk: cm.walkables.filter(w => w.tag === `interior:${id}`).length,
    }));
  });
  const bad = res.filter(r => r.state !== 'loaded' || r.col < 1);
  console.log('[stepwalk] 预加载 S 档内景：' + res.map(r => `${r.id}=${r.state}(COL ${r.col}/WALK ${r.walk})`).join(' '));
  if (bad.length) throw new Error('S 档内景预加载失败：' + bad.map(r => `${r.id}(state=${r.state}, COL=${r.col})`).join(', '));
  return res;
}

async function openPage() {
  const browser = await chromium.launch({ executablePath: browserExecutablePath(), headless: true, args: ['--enable-webgl', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 320, height: 200 } });
  await page.goto(process.env.PALACE_URL || 'http://127.0.0.1:5173', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__forbiddenCityApp?.controls && document.querySelector('#loading-screen').style.display === 'none', null, { timeout: 240000 });
  if (process.env.STEPWALK_NO_INTERIORS !== '1') {
    try { await preloadInteriors(page); } catch (e) { await browser.close(); throw e; }
  } else console.log('[stepwalk] STEPWALK_NO_INTERIORS=1：跳过 S 档内景预加载（仅调试）');
  return { browser, page };
}

// Explicit metadata only. Legacy callers remain two-element tuples and retain
// their original loop below; unknown opt-ins must never silently fall back.
function routeForBrowser(route) {
  return [route.name, route.pts, route.waypointDriver === undefined ? {} : { waypointDriver: route.waypointDriver }];
}

/** routes: [[name, pts, optionalDriverMetadata]]；返回每条 × fps × sprint 的结果 */
async function runRoutes(page, routes, fpsList, sprints) {
  for (const [, , options] of routes) {
    if (options?.waypointDriver !== undefined && !['physical-crossing-v1', 'zhaode-physical-crossing-v1'].includes(options.waypointDriver)) {
      throw new Error(`Unsupported waypointDriver: ${options.waypointDriver}`);
    }
  }
  return page.evaluate(async ({ ROUTES, fpsList, sprints }) => {
    const physicalModules = ROUTES.some(([, , options]) => options?.waypointDriver === 'physical-crossing-v1')
      ? await Promise.all([import('/tests/lib/physical-waypoints.mjs'), import('/tests/lib/terrace-walk.mjs')]) : null;
    const zhaodeModule = ROUTES.some(([, , options]) => options?.waypointDriver === 'zhaode-physical-crossing-v1')
      ? await import('/tests/lib/zhaode-walk.mjs') : null;
    const a = window.__forbiddenCityApp;
    cancelAnimationFrame(a.animationFrame);
    a.disposed = true; // 停掉主循环，由本脚本逐帧驱动
    const c = a.controls;
    const zm = a.zoneManager;
    Object.defineProperty(c.controls, 'isLocked', { get: () => true, configurable: true });
    // 台基投影（box 型可行走面中顶面 >= 1m 的），用于判断"在台基里面却站在 0 高度"
    // rescue:false 的是城台顶面（下方有门洞贯通），穿门洞时脚点在 0 属正常，不算"掉到台下"
    // 分区流式加载会增删 walkables：已加载分区集合变化时重算台基列表
    let terraces = [], terraceKey = null;
    const refreshTerraces = () => {
      const key = zm ? zm.getLoadedIds().join(',') : 'static';
      if (key === terraceKey) return;
      terraceKey = key;
      terraces = a.collisionManager.walkables.filter(w => w.type === 'box' && w.rescue !== false && w.box.max.y >= 1).map(w => w.box);
    };
    const under = (x, z, feet) => { refreshTerraces(); return terraces.some(b => x > b.min.x + 1 && x < b.max.x - 1 && z > b.min.z + 1 && z < b.max.z - 1 && feet < b.max.y - 1.2); };
    // 主循环已停，由本脚本代为推进分区加载（与 animate() 中的调用一致）
    const tickZones = () => zm?.update({ x: a.camera.position.x, z: a.camera.position.z });
    // 碰撞体 tag 集合（碰撞体数量变化时重算）
    let tagSet = new Set(), tagCount = -1;
    const colliderTags = () => {
      const cs = a.collisionManager.colliders;
      if (cs.length !== tagCount) { tagCount = cs.length; tagSet = new Set(cs.map(c => c.tag)); }
      return tagSet;
    };
    // 分区事件记录（包一层 loadZone/unloadZone，不改行为）
    const events = [];
    if (zm && !zm.__p1tWrapped) {
      const L = zm.loadZone.bind(zm), U = zm.unloadZone.bind(zm);
      zm.loadZone = id => { const had = zm.loaded.has(id); L(id); if (!had && zm.loaded.has(id)) events.push('+' + id); };
      zm.unloadZone = id => { const had = zm.loaded.has(id); U(id); if (had) events.push('-' + id); };
      zm.__p1tWrapped = true;
    }
    const out = [];
    function runPhysicalRoute(name, pts, fps, sprint) {
      const [{ createPhysicalWaypointDriver }, { traceTerraceGround, terraceTraceSummary }] = physicalModules;
      const terrace = a.palaceBuilder.terraceProfiles.find(p => p.id === 'three-hall-waist-stairs');
      if (!terrace) throw new Error('Physical waist-route profile missing from runtime');
      const side = pts[0][0] < 0 ? 'east' : 'west';
      const [x, z] = pts[0];
      zm?.ensureLoadedAt(x, z); tickZones(); events.length = 0;
      c.setPosition(x, 1.7, z); // Real outside-ground start, never highest-surface spawn.
      if (Math.abs(c.feetY) > 1e-7) throw new Error('Physical waist route must start with feet=0');
      c.velocity.set(0, 0, 0); c.moveForward = true;
      const physical = () => [a.camera.position.x - c.bobOffset.x, a.camera.position.z - c.bobOffset.z];
      const driver = createPhysicalWaypointDriver(pts), trace = traceTerraceGround(a.collisionManager, terrace);
      const dt = 1 / fps, profile = [], zonesSeen = [];
      let maxFeet = 0, maxSpeed = 0, bad = null, stuckAt = null, unloadedWalk = 0;
      let legFrames = 0, stuck = 0, last = physical(), frame = 0;
      try {
        while (!driver.complete) {
          const before = physical(), command = driver.command(before, sprint), [tx, tz] = command.target;
          c.canSprint = command.canSprint;
          a.camera.position.sub(c.bobOffset);
          a.camera.lookAt(tx, a.camera.position.y, tz);
          a.camera.position.add(c.bobOffset);
          a.camera.updateMatrixWorld(true);
          tickZones(); c.prevTime = performance.now() - dt * 1000; c.update();
          const after = physical(), p = a.camera.position;
          maxFeet = Math.max(maxFeet, c.feetY); maxSpeed = Math.max(maxSpeed, c.motion.speed);
          if (frame++ % Math.max(1, Math.round(fps / 2)) === 0) profile.push(+c.feetY.toFixed(1));
          if (!bad && under(p.x, p.z, c.feetY) && c.verticalVelocity === 0) bad = [+p.x.toFixed(1), +p.z.toFixed(1), +c.feetY.toFixed(2)];
          const zid = zm?.findZone(p.x, p.z);
          if (zid && zonesSeen.at(-1) !== zid) zonesSeen.push(zid);
          if (zid && !colliderTags().has(zid)) unloadedWalk += Math.hypot(after[0] - before[0], after[1] - before[1]);
          if (driver.observe(before, after)) { legFrames = 0; stuck = 0; last = after; continue; }
          legFrames++;
          if (legFrames % fps === 0) { stuck = Math.hypot(after[0] - last[0], after[1] - last[1]) < 0.3 ? stuck + 1 : 0; last = after; }
          const k = driver.index, limit = Math.ceil(Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]) / 2 * fps) + fps * 4;
          if (stuck >= 2 || legFrames >= limit) { stuckAt = pts[k]; break; }
        }
        c.moveForward = false;
        if (driver.complete) for (let i = 0; i < fps * 2; i++) { tickZones(); c.prevTime = performance.now() - dt * 1000; c.update(); }
        const support = terraceTraceSummary(trace.samples, terrace, side), p = a.camera.position;
        const supported = support.ascending.length === 3 && support.descending.length === 3 && support.unsafe.length === 0;
        return { fps, sprint, name, arrived: driver.complete && supported && Math.abs(c.feetY) < 0.02, stuckAt,
          end: [+p.x.toFixed(1), +p.z.toFixed(1), +c.feetY.toFixed(2)], maxFeet: +maxFeet.toFixed(2), maxSpeed, fellUnder: bad, profile,
          zonesSeen, zoneEvents: [...events], unloadedWalk: +unloadedWalk.toFixed(2), waypointDriver: 'physical-crossing-v1',
          speedProtocol: sprint ? 'sprint with corner braking within2m' : 'slow', driver: driver.diagnostics, support };
      } finally { c.moveForward = false; trace.restore(); }
    }
    for (const fps of fpsList) for (const sprint of sprints) for (const [name, pts, options] of ROUTES) {
      if (options?.waypointDriver === 'zhaode-physical-crossing-v1') {
        zm?.ensureLoadedAt(...pts[0]);
        const profile = zhaodeModule.runtimeZhaodeProfile(a);
        events.length = 0;
        const result = zhaodeModule.runZhaodeRoute(a, profile, pts, { fps, sprint });
        out.push({ name, ...result, profile: [], zoneEvents: [...events] });
        continue;
      }
      if (options?.waypointDriver === 'physical-crossing-v1') { out.push(runPhysicalRoute(name, pts, fps, sprint)); continue; }
      const [x0, z0] = pts[0];
      // 传送到起点后先把该处分区建好（真实游玩中靠 40m 预载，传送是瞬移所以要补齐）
      a.camera.position.set(x0, a.camera.position.y, z0);
      zm?.ensureLoadedAt(x0, z0);
      tickZones();
      events.length = 0;
      c.setPosition(x0, 300, z0); // 起点取该处最高可行走面（起点在台基上时站在台面上）
      c.velocity.set(0, 0, 0);
      c.moveForward = true;
      c.canSprint = sprint;
      const dt = 1 / fps;
      let maxFeet = 0, bad = null, arrived = true, stuckAt = null, unloadedWalk = 0;
      const zonesSeen = [];
      const profile = [];
      for (let k = 1; k < pts.length && arrived; k++) {
        const [x1, z1] = pts[k];
        const p0 = a.camera.position;
        const limit = Math.ceil(Math.hypot(x1 - p0.x, z1 - p0.z) / 2 * fps) + fps * 4;
        let stuck = 0, last = [p0.x, p0.z], reached = false;
        for (let f = 0; f < limit; f++) {
          c.prevTime = performance.now() - dt * 1000;
          a.camera.lookAt(x1, a.camera.position.y, z1);
          tickZones();
          const bx = a.camera.position.x, bz = a.camera.position.z;
          c.update();
          const p = a.camera.position;
          if (zm) {
            const zid = zm.findZone(p.x, p.z);
            if (zid && zonesSeen[zonesSeen.length - 1] !== zid) zonesSeen.push(zid);
            // 直接查碰撞体：所在区没有任何带该区 tag 的碰撞体 = 碰撞缺失
            if (zid && !colliderTags().has(zid)) unloadedWalk += Math.hypot(p.x - bx, p.z - bz);
          }
          maxFeet = Math.max(maxFeet, c.feetY);
          if (f % Math.max(1, Math.round(fps / 2)) === 0) profile.push(+c.feetY.toFixed(1));
          if (!bad && under(p.x, p.z, c.feetY) && c.verticalVelocity === 0) bad = [+p.x.toFixed(1), +p.z.toFixed(1), +c.feetY.toFixed(2)];
          if (Math.hypot(p.x - x1, p.z - z1) < 0.8) { reached = true; break; }
          if (f % fps === 0 && f > 0) {
            if (Math.hypot(p.x - last[0], p.z - last[1]) < 0.3) stuck++; else stuck = 0;
            last = [p.x, p.z];
            if (stuck >= 2) break;
          }
        }
        if (!reached) { arrived = false; stuckAt = pts[k]; }
      }
      c.moveForward = false;
      const p = a.camera.position;
      out.push({ fps, sprint, name, arrived, stuckAt, end: [+p.x.toFixed(1), +p.z.toFixed(1), +c.feetY.toFixed(2)], maxFeet: +maxFeet.toFixed(2), fellUnder: bad, profile,
        zonesSeen, zoneEvents: [...events], unloadedWalk: +unloadedWalk.toFixed(2) });
    }
    return out;
  }, { ROUTES: routes, fpsList, sprints });
}

