import { FirstPersonControls } from '../../src/controls/FirstPerson.js';
import { PLAYER } from '../../src/config/constants.js';
import { createPhysicalWaypointDriver } from './physical-waypoints.mjs';

/** Reproduce the production candidate/eligibility/max/tie rules using the
 * actual current walkables. This is a read-only diagnostic, not a height source.
 * The returned height is cross-checked against the real getGroundHeight result.
 */
function selectedGroundSupport(cm, x, z, feet, stepUp) {
  let ground=0, rescue=0, selected=null, rescuedBy=null;
  const limit=feet+stepUp;
  for(let index=0;index<cm.walkables.length;index++) {
    const w=cm.walkables[index];
    let top;
    if(w.type==='box') {
      const b=w.box;
      if(x<b.min.x||x>b.max.x||z<b.min.z||z>b.max.z)continue;
      top=b.max.y;
      if(w.rescue&&top>limit&&x>b.min.x+.6&&x<b.max.x-.6&&z>b.min.z+.6&&z<b.max.z-.6&&top>rescue) {
        rescue=top;rescuedBy={walkable:w,index};
      }
    } else {
      if(x<w.minX||x>w.maxX||z<w.minZ||z>w.maxZ)continue;
      const a=w.axis==='x'?x:z;
      const t=w.a1===w.a0?1:Math.min(1,Math.max(0,(a-w.a0)/(w.a1-w.a0)));
      if(w.crossMin0!==undefined) {
        const cross=w.axis==='x'?z:x;
        const low=w.crossMin0+(w.crossMin1-w.crossMin0)*t;
        const high=w.crossMax0+(w.crossMax1-w.crossMax0)*t;
        if(cross<low-1e-9||cross>high+1e-9)continue;
      }
      top=w.y0+(w.y1-w.y0)*t;
    }
    // Production uses strict greater-than: the first eligible equal-height
    // primitive wins; a height-zero ramp never replaces initial ground zero.
    if(top>limit||top<=ground)continue;
    ground=top;selected={walkable:w,index};
  }
  return rescue>ground?{height:rescue,selected:rescuedBy,rescue:true}:{height:ground,selected,rescue:false};
}

/** Test-only instrumentation: labels an actual selected primitive, never just
 * an expected profile height. Production movement and rescue are unchanged. */
export function traceTerraceGround(cm, profile) {
  const original=cm.getGroundHeight, samples=[];
  const rampKeys=['axis','minX','maxX','minZ','maxZ','a0','a1','y0','y1',
    'crossMin0','crossMax0','crossMin1','crossMax1'];
  cm.getGroundHeight=function(x,z,feet=0,stepUp=.6) {
    const height=original.call(this,x,z,feet,stepUp);
    const actual=selectedGroundSupport(this,x,z,feet,stepUp),w=actual.selected?.walkable;
    let source;
    if(Math.abs(actual.height-height)>1e-9)source='unverified';
    else if(actual.rescue)source='rescue';
    else if(!w)source='ground';
    else if(w.type==='box')source='box';
    else {
      const flight=profile.flights.find(f=>rampKeys.every(key=>w[key]===f.ramp[key]));
      source=flight?.id??'other-ramp';
    }
    samples.push({x,z,feetIn:feet,height,source,supportIndex:actual.selected?.index??null,supportType:w?.type??'ground'});
    return height;
  };
  return {samples,restore:()=>{cm.getGroundHeight=original;}};
}

export function terraceTraceSummary(samples, profile, side) {
  const flights=profile.flights.filter(f=>f.side===side);
  const waist=samples.filter(p=>Math.abs(p.z-profile.centerZ)<.8&&Math.abs(p.x)>=Math.abs(flights.at(-1).xEdge)-.1&&Math.abs(p.x)<=Math.abs(flights[0].xToe)+.1);
  const ascending=flights.filter(f=>waist.some(p=>p.source===f.id&&p.height-p.feetIn>1e-5)).map(f=>f.id);
  const descending=flights.filter(f=>waist.some(p=>p.source===f.id&&p.height-p.feetIn< -1e-5)).map(f=>f.id);
  const unsafe=waist.filter(p=>p.source==='rescue'||p.source==='unverified'||p.source==='unsupported'||p.height-p.feetIn>.15625+1e-6);
  return {ascending,descending,unsafe,maxRise:Math.max(0,...waist.map(p=>p.height-p.feetIn)),samples:waist.length};
}

/** Real FirstPersonControls with only DOM event targets and its clock stubbed.
 * Start feet=0, not an infinite/high spawn. Backward mode uses actual S motion. */
export function replayTerrace(t,W,points,{fps=60,sprint=false,backward=false,recordFrames=false}={}) {
  const oldDoc=globalThis.document,oldWindow=globalThis.window,noop=()=>{};
  const doc={...oldDoc,addEventListener:noop,removeEventListener:noop,exitPointerLock:noop};
  globalThis.document=doc;globalThis.window={addEventListener:noop,removeEventListener:noop};
  let now=0;const clock=t.mock.method(performance,'now',()=>now);
  const camera=new W.THREE.PerspectiveCamera();
  const controls=new FirstPersonControls(camera,{ownerDocument:doc,addEventListener:noop,removeEventListener:noop},W.cm);
  controls.controls.isLocked=true;
  controls.setPosition(points[0][0],PLAYER.HEIGHT,points[0][1]);
  const startFeet=controls.feetY;
  controls.moveForward=!backward;controls.moveBackward=backward;controls.canSprint=sprint;
  let maxFeet=0;
  const frames=[];
  try {
    const physical=()=>[camera.position.x-controls.bobOffset.x,camera.position.z-controls.bobOffset.z];
    const driver=createPhysicalWaypointDriver(points);
    let legFrames=0,stuck=0,last=physical(),maxSpeed=0;
    while(!driver.complete) {
      const before=physical(),command=driver.command(before,sprint),[x,z]=command.target;
      controls.canSprint=command.canSprint;
      now+=1000/fps;
      // Mouse aim is based on the unbobbed physical position, and continuous
      // collinear stair contacts do not cause artificial direction reversals.
      camera.position.sub(controls.bobOffset);
      camera.lookAt(backward?2*camera.position.x-x:x,camera.position.y,backward?2*camera.position.z-z:z);
      camera.position.add(controls.bobOffset);
      camera.updateMatrixWorld(true);
      controls.update();maxFeet=Math.max(maxFeet,controls.feetY);
      const after=physical();
      maxSpeed=Math.max(maxSpeed,controls.motion.speed);
      if(recordFrames)frames.push({time:now/1000,x:after[0],z:after[1],feet:controls.feetY,ground:controls.groundY,
        speed:controls.motion.speed,sprintInput:controls.canSprint,waypoint:driver.index});
      if(driver.observe(before,after)){legFrames=0;stuck=0;last=after;continue;}
      const k=driver.index;
      legFrames++;
      if(legFrames%fps===0){stuck=Math.hypot(after[0]-last[0],after[1]-last[1])<.3?stuck+1:0;last=after;}
      const limit=Math.ceil(Math.hypot(points[k][0]-points[k-1][0],points[k][1]-points[k-1][1])/2*fps)+fps*4;
      if(stuck>=2||legFrames>=limit)return{arrived:false,stuckAt:points[k],startFeet,maxFeet,maxSpeed,driver:driver.diagnostics,...(recordFrames?{frames}:{}),end:[camera.position.x,camera.position.z,controls.feetY]};
    }
    controls.moveForward=false;controls.moveBackward=false;
    for(let i=0;i<fps*2;i++){now+=1000/fps;controls.update();}
    return{arrived:true,startFeet,maxFeet,maxSpeed,driver:driver.diagnostics,...(recordFrames?{frames}:{}),end:[camera.position.x,camera.position.z,controls.feetY]};
  } finally {controls.dispose();clock.mock.restore();globalThis.document=oldDoc;globalThis.window=oldWindow;}
}

import { createPhysicalWaypointDriver } from './physical-waypoints.mjs';
import { bindProfileSupports, traceProfileSupports, profileSupportReport } from './profile-support-trace.mjs';

export const ZHAODE_WAYPOINT_DRIVER='zhaode-physical-crossing-v1';
export function zhaodeRoutePoints(profile,{from='front',offset=0}={}) {
  const names=['frontGround','frontToe','frontTop','portalFront','portalRear','rearTop','rearToe','rearGround'];
  const c=Math.cos(profile.rot),s=Math.sin(profile.rot);
  let go=names.map(name=>{const [lx,lz]=profile.routeContacts[name],x=lx+offset;return [profile.x+x*c+lz*s,profile.z-x*s+lz*c];});
  if(from==='rear')go=go.reverse();
  return [...go,...go.slice(0,-1).reverse()];
}

/** Drive the application's actual controller; diagnostic observers never supply
 * heights, positions or velocities after the single ground-origin reset. The
 * established physical waypoint contract retains inertia and endpoint braking. */
export function runZhaodeRoute(app,profile,points,{fps=60,sprint=false,backward=false,from='front',
  identities,recordFrames=false,eyeHeight=1.7,stepUp=.6,tickZones=true}={}) {
  const c=app.controls,cm=app.collisionManager,camera=app.camera,zm=app.zoneManager;
  const tick=()=>{if(tickZones)zm?.update({x:camera.position.x,z:camera.position.z});};
  const [x,z]=points[0];
  if(tickZones)zm?.ensureLoadedAt(x,z);
  c.stop();c.setPosition(x,eyeHeight,z);tick();
  const startFeet=c.feetY;
  if(Math.abs(startFeet)>1e-7)throw new Error('昭德 physical route must begin feet=0 outside the actual toe');
  const supports=identities??bindProfileSupports(cm,profile),trace=traceProfileSupports(cm,supports);
  const physical=()=>[camera.position.x-c.bobOffset.x,camera.position.z-c.bobOffset.z];
  const driver=createPhysicalWaypointDriver(points),dt=1/fps,frames=[],feetFailures=[],zonesSeen=[];
  c.moveForward=!backward;c.moveBackward=backward;
  let maxFeet=0,maxSpeed=0,maxFeetGroundSeparation=0,stuckAt=null,legFrames=0,stuck=0,last=physical(),unloadedWalk=0;
  const cos=Math.cos(profile.rot),sin=Math.sin(profile.rot);
  const sample=()=>{
    const pos=physical(),lx=(pos[0]-profile.x)*cos-(pos[1]-profile.z)*sin,lz=(pos[0]-profile.x)*sin+(pos[1]-profile.z)*cos;
    maxFeet=Math.max(maxFeet,c.feetY);maxSpeed=Math.max(maxSpeed,c.motion.speed);
    maxFeetGroundSeparation=Math.max(maxFeetGroundSeparation,Math.abs(c.feetY-c.groundY));
    if(Math.abs(lx)<profile.platform.width/2-.5&&Math.abs(lz)<profile.platform.depth/2-.5&&
      (c.feetY<=profile.platform.topY-stepUp||Math.abs(c.groundY-profile.platform.topY)>1e-7))feetFailures.push({x:pos[0],z:pos[1],feet:c.feetY,ground:c.groundY});
    if(recordFrames)frames.push({x:pos[0],z:pos[1],feet:c.feetY,ground:c.groundY,speed:c.motion.speed});
    return pos;
  };
  try{
    while(!driver.complete){
      const before=physical(),command=driver.command(before,sprint),[tx,tz]=command.target;
      c.canSprint=command.canSprint;
      camera.position.sub(c.bobOffset);
      camera.lookAt(backward?2*camera.position.x-tx:tx,camera.position.y,backward?2*camera.position.z-tz:tz);
      camera.position.add(c.bobOffset);camera.updateMatrixWorld(true);
      tick();c.prevTime=performance.now()-dt*1000;c.update();const after=sample();
      const zid=zm?.findZone(after[0],after[1]);
      if(zid&&zonesSeen.at(-1)!==zid)zonesSeen.push(zid);
      if(zid&&!cm.colliders.some(col=>col.tag===zid))unloadedWalk+=Math.hypot(after[0]-before[0],after[1]-before[1]);
      if(driver.observe(before,after)){legFrames=0;stuck=0;last=after;continue;}
      legFrames++;
      if(legFrames%fps===0){stuck=Math.hypot(after[0]-last[0],after[1]-last[1])<.3?stuck+1:0;last=after;}
      const k=driver.index,limit=Math.ceil(Math.hypot(points[k][0]-points[k-1][0],points[k][1]-points[k-1][1])/2*fps)+fps*4;
      if(stuck>=2||legFrames>=limit){stuckAt=points[k];break;}
    }
    c.moveForward=false;c.moveBackward=false;
    if(driver.complete)for(let i=0;i<fps*2;i++){tick();c.prevTime=performance.now()-dt*1000;c.update();sample();}
    const support=profileSupportReport(trace.samples,profile,from),end=physical();
    return {fps,sprint,backward,from,startFeet,xyArrived:driver.complete,
      arrived:driver.complete&&support.valid&&feetFailures.length===0&&Math.abs(c.feetY)<.02,
      stuckAt,end:[...end,c.feetY],maxFeet,maxSpeed,maxFeetGroundSeparation,zonesSeen,unloadedWalk,
      fellUnder:feetFailures[0]??null,feetFailures:feetFailures.slice(0,8),support,driver:driver.diagnostics,
      waypointDriver:ZHAODE_WAYPOINT_DRIVER,...(recordFrames?{frames}:{})};
  }finally{c.moveForward=false;c.moveBackward=false;trace.restore();}
}

/** Locate permanent B metadata, with no S-loader dependency. */
export function runtimeZhaodeProfile(app) {
  let result;
  app.scene.traverse(object=>{for(const entry of object.userData.architecture??[])if(entry.gateProfile==='zhaode'||entry.profile==='zhaode'){
    const candidate=entry.geometry??entry.gateGeometry??entry;
    if(candidate.supports&&candidate.routeContacts)result=candidate;
  }});
  if(!result)throw new Error('Permanent B 昭德 runtime geometry/support profile is missing');
  return result;
}

const { browserExecutablePath } = require('./lib/browser-path.cjs');
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: browserExecutablePath(), headless: true, args: ['--enable-webgl', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  try {
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    await page.goto(process.env.PALACE_URL);
    await page.waitForFunction(() => window.__forbiddenCityApp?.teleport && document.querySelector('#loading-screen').style.display === 'none', null, { timeout: 120000 });
    const rows = await page.evaluate(async () => {
      const a = window.__forbiddenCityApp;
      cancelAnimationFrame(a.animationFrame);
      const { TELEPORT, PLAYER } = await import('/src/config/constants.js');
      const { Vector3 } = await import('/node_modules/three/build/three.module.js');
      const names = [...new Set([...TELEPORT.POINTS.map(p => p.target), ...a.minimap.labels.map(p => p.name)])];
      return names.map(name => {
        const point = a.teleport.go(name);
        const g = a.teleport.geometryFor(name);
        const landing = point ?? a.teleport.landingFor(name);
        if (!point) {
          const cm = a.collisionManager;
          const y = cm.getGroundHeight(landing.x, landing.z, Infinity);
          const overlaps = cm.colliders.filter(c => c.box.min.x < landing.x + 0.5 && c.box.max.x > landing.x - 0.5 && c.box.min.z < landing.z + 0.5 && c.box.max.z > landing.z - 0.5 && c.box.min.y < y + PLAYER.HEIGHT && c.box.max.y > y + 0.35).map(c => ({ name: c.object?.name ?? c.tag, min: c.box.min.toArray(), max: c.box.max.toArray() }));
          return { name, ...landing, y, overlaps, pass: false, reason: '落点碰撞' };
        }
        const p = a.controls.getPosition();
        const feet = a.controls.getFeetY();
        const ground = a.collisionManager.getGroundHeight(p.x, p.z, Infinity);
        const facing = a.camera.getWorldDirection(new Vector3()).dot(new Vector3(landing.lookAtX - p.x, 0, landing.lookAtZ - p.z).normalize());
        const zone = a.zoneManager.findZone(landing.lookAtX, landing.lookAtZ) ?? a.zoneManager.findZone(p.x, p.z);
        const loaded = !zone || a.zoneManager.getLoadedIds().includes(zone);
        // 前行验收（总控 10-12 批准）：朝正面中点走，有效前进 ≥ MIN_WALK，或走到离正面 ≤ NEAR_FRONT
        const fx = g.frontX - p.x, fz = g.frontZ - p.z, toFront = Math.hypot(fx, fz);
        const walk = Math.min(TELEPORT.PROBE_WALK, toFront);
        const end = a.collisionManager.getValidPosition(p, new Vector3(p.x + fx / toFront * walk, p.y, p.z + fz / toFront * walk), 0.5, feet, PLAYER.STEP_UP);
        const progressed = ((end.x - p.x) * fx + (end.z - p.z) * fz) / toFront;
        const remain = Math.hypot(g.frontX - end.x, g.frontZ - end.z);
        const overlap = a.collisionManager.checkCollision(p);
        const walkOk = progressed >= TELEPORT.MIN_WALK || remain <= TELEPORT.NEAR_FRONT;
        return { name, x: +p.x.toFixed(2), z: +p.z.toFixed(2), feet: +feet.toFixed(2), zone, dist: point.distance, lateral: point.lateral, fallback: point.fallback, facing: +facing.toFixed(3), walked: +progressed.toFixed(2), remain: +remain.toFixed(2), loaded, overlap, pass: loaded && !overlap && Math.abs(feet - ground) < 0.01 && facing > 0.999 && walkOk };
      });
    });
    console.table(rows);
    console.log(JSON.stringify(rows));
    if (rows.some(r => !r.pass)) process.exitCode = 1;
  } finally { await browser.close(); }
})().catch(e => { console.error(e); process.exit(1); });
